  insert into public.kit_completions (user_id, kit, period_key, payload, local_date)
    insert into public.xp_events (user_id, source, amount, ref_id, local_date, iso_week)
  insert into public.lens_progress (user_id, theme, last_card_order, updated_at)
insert into public.lens_cards (theme, sort_order, headline, body) values
  ('expression', 1, 'You don''t have to perform ''fine'' all the time.', 'Constantly appearing okay takes real energy. It''s fine to let your face match your actual mood sometimes, around the right people, in the right moments.'),
  ('expression', 2, 'Unspoken frustration doesn''t disappear, it just changes shape.', 'Staying quiet about what''s bothering you often turns into distance, snapping, or resentment later. Naming it early, even briefly, is usually kinder to the relationship.'),
  ('expression', 3, 'Needing help isn''t the same as failing at something.', 'Asking for support is often mistaken for weakness, but it''s really just accurate information-sharing. People can''t help with what they don''t know you''re carrying.'),
  ('expression', 4, 'Silence in the room isn''t neutral, it''s still a choice.', 'Staying quiet to avoid friction can feel safe, but it also means your perspective never gets to shape the outcome. One sentence can be enough to be heard.'),
  ('expression', 5, 'Tired is a fact, not a confession.', 'You don''t need to justify being worn out before you''re allowed to say it. Naming exhaustion out loud is often the first step toward actually resting.'),
  ('expression', 6, 'A smile doesn''t have to cover the whole story.', 'It''s possible to be genuinely okay in some ways and quietly sad in others. You don''t have to pick one face to wear for everyone around you.'),
  ('expression', 7, 'The words feel risky because they matter, that''s the point.', 'Vulnerable language feels exposed precisely because it''s honest. The discomfort isn''t a sign to stay quiet; it''s often a sign the words are worth saying.'),
  ('expression', 8, 'Letting a wrong story about you stand isn''t the same as peace.', 'Staying silent when someone gets you wrong can feel like taking the high road, but it can also just mean you''re carrying someone else''s version of you.'),
  ('expression', 9, 'Keeping the peace sometimes just means keeping the tension inside you.', 'Swallowing anger to avoid conflict doesn''t make the feeling go away, it usually just relocates it inward, where it costs you more over time.'),
  ('expression', 10, '''I''m fine'' is allowed to be a placeholder, not a permanent answer.', 'It''s okay to say you''re fine to get through the moment. Just notice if it becomes the only thing you ever say, even to people who''d actually want to know more.'),
  ('expression', 11, 'Agreeing out loud while disagreeing inside costs more than it looks like.', 'Going along with the group to avoid standing out can feel easier in the moment, but it slowly teaches you your own view doesn''t count as much.'),
  ('expression', 12, 'Grief doesn''t need an audience, but it isn''t meant to be carried entirely alone.', 'You get to choose how much of your grief you share and with whom. Just make sure ''private'' doesn''t quietly become ''unspoken to anyone at all.'''),
  ('expression', 13, 'Every yes you didn''t mean is a no you didn''t say.', 'Saying yes to avoid disappointing someone often just delays the disappointment, and adds your own resentment on top of it. A clear no can be more respectful than a reluctant yes.'),
  ('expression', 14, 'Looking confident and feeling confident aren''t the same job.', 'You can do good work while privately unsure of yourself, most people are. Hiding that fear from everyone doesn''t make you more capable, just more alone in it.'),
  ('expression', 15, 'A friendship can survive honesty better than it survives silence.', 'Staying quiet to protect a friendship can end up eroding it instead, the hurt doesn''t disappear, it just sits underneath everything else you say to each other.'),
  ('expression', 16, 'Caring out loud isn''t a character flaw.', 'Downplaying excitement to seem unbothered can become a habit that quietly disconnects you from the things you actually enjoy. It''s allowed to show.'),
  ('expression', 17, 'Your partner isn''t a mind reader, even a good one.', 'Hoping someone will notice what you need without you saying it puts a lot of weight on guesswork. Naming a need directly gives it an actual chance of being met.'),
  ('expression', 18, 'Capacity has a limit, even for people who are good at their job.', 'Staying quiet about being overwhelmed often means the workload keeps growing until something breaks. Flagging it early is normal, not a failure.'),
  ('expression', 19, 'Some things get heavier the longer they''re carried alone.', 'Not every secret needs to be shared, but some grow harder to hold the longer they stay unspoken. It''s worth asking who you could tell, even just one person.'),
  ('expression', 20, 'The question you''re not asking, someone else probably has too.', 'Staying silent to avoid looking uninformed usually just means staying uninformed longer. Most ''obvious'' questions are less obvious than they feel.'),
  ('expression', 21, 'Disappointment is a normal reaction, not an overreaction.', 'Brushing off disappointment to seem easygoing doesn''t make the feeling smaller, it just makes it invisible to the people who could actually understand.'),
  ('expression', 22, 'Not caring is sometimes just caring with the volume turned down.', 'Acting indifferent can feel like armor, but it often just means the feeling goes underground instead of away. It''s still there, doing its work quietly.'),
  ('expression', 23, 'Family harmony built on silence is still built on something missing.', 'Going along with family expectations to avoid conflict can keep the peace on the surface, while your actual opinion never gets a seat at the table.'),
  ('expression', 24, 'Tears in public aren''t proof that something''s wrong with you.', 'Crying in front of others can feel exposing, but it''s just a normal, human response to feeling something strongly. It doesn''t require an apology.'),
  ('expression', 25, 'Fear named out loud tends to shrink; fear held in tends to grow.', 'Saying ''I''m scared'' can feel like giving the fear power, but it usually does the opposite, it turns a vague, looming feeling into something specific enough to face.'),
  ('expression', 26, 'Pride doesn''t have to be quiet to stay humble.', 'Downplaying something you''re proud of to avoid seeming boastful can slowly teach you to minimize your own wins. You''re allowed to just say it plainly.'),
  ('expression', 27, 'Staying quiet about your work doesn''t make it speak louder.', 'Assuming good work will be noticed on its own often means it isn''t. Naming your contribution clearly isn''t bragging, it''s giving people accurate information.'),
  ('expression', 28, 'Money stays awkward longer when it stays unspoken.', 'Avoiding money conversations can feel like avoiding conflict, but it usually just delays it. A direct conversation is often shorter than the silence around it.'),
  ('expression', 29, 'They can''t adjust to something they don''t know is a problem.', 'Staying silent about a behavior that bothers you protects the moment, but it also removes any real chance of things actually changing.'),
  ('expression', 30, 'Jealousy is information before it''s a flaw.', 'The urge to hide jealousy often comes from judging it too quickly. Before pushing it away, it can help to just notice what it''s actually pointing to.'),
  ('expression', 31, 'Peace that depends on nobody being honest isn''t peace, it''s a pause.', 'Staying quiet through tense family moments can look like harmony, but the tension usually just resurfaces later, in smaller and less direct ways.'),
  ('expression', 32, 'Loneliness doesn''t go away because no one knows about it.', 'It can feel embarrassing to admit you''re lonely, especially if your life looks full from the outside. Saying it plainly is often the first step toward it changing.'),
  ('expression', 33, 'An unsaid compliment helps exactly no one.', 'Thinking something kind and not saying it costs nothing to keep quiet, but it also costs the other person something they never got to hear.'),
  ('expression', 34, 'A goal doesn''t have to be finished to be worth saying out loud.', 'Keeping ambitions private can feel like protection, but it can also mean you never get support, feedback, or accountability for what you actually want.'),
  ('expression', 35, 'Small frustrations left unsaid tend to merge into one big one.', 'Letting minor irritations go unspoken can feel easygoing, but they often accumulate quietly until a small moment triggers a much bigger reaction.'),
  ('expression', 36, '''How are you'' is allowed to get a real answer sometimes.', 'Automatically saying ''good'' can become such a reflex it stops being a choice. Occasionally answering honestly gives people a real chance to show up for you.'),
  ('expression', 37, 'A conversation postponed doesn''t get smaller while it waits.', 'Putting off a hard conversation can feel like avoiding discomfort now, but the issue usually keeps growing until it''s harder to raise than it would''ve been earlier.'),
  ('expression', 38, 'A boundary isn''t a punishment for the other person.', 'Guilt can make boundaries feel selfish, but a boundary is just information about what you can and can''t hold, not a judgment of anyone else.'),
  ('expression', 39, 'Needing things isn''t the same as being difficult.', 'Shrinking your needs to seem easy to be around can work for a while, but it means the people close to you never learn the real scale of what you''re carrying.'),
  ('expression', 40, 'Burnout rarely announces itself before it''s already arrived.', 'Pushing through exhaustion without naming it often means the first real sign anyone notices is a full stop, not a warning. Saying it early changes that timeline.'),
  ('expression', 41, 'Changing your mind isn''t a contradiction, it''s an update.', 'Sticking with an old opinion just to seem consistent can keep you stuck in a position you don''t actually hold anymore. It''s fine to just say things shifted.'),
  ('expression', 42, 'Avoiding one argument now can plant a longer one later.', 'Softening the truth to keep things calm can prevent a conversation today, but half-truths tend to surface eventually, usually at a less convenient time.'),
  ('expression', 43, 'Thank you doesn''t need to be eloquent to count.', 'Feeling awkward about expressing gratitude can keep it locked inside, but most people would rather hear a clumsy thank-you than none at all.'),
  ('expression', 44, '''It was just a joke'' doesn''t cancel out how it landed.', 'Laughing off something that actually stung can protect the moment, but it also teaches people the joke was fine, even when it wasn''t.'),
  ('expression', 45, 'Missing someone out loud isn''t a weakness, it''s information for them too.', 'Keeping how much you miss someone to yourself can feel safer, but it also means they never get the chance to know they matter that much to you.'),
  ('expression', 46, 'Unnamed stress tends to leak out sideways.', 'Stress that never gets acknowledged directly often shows up as snapping at small things instead. Naming the real source usually calms the smaller reactions too.'),
  ('expression', 47, 'Needing space doesn''t mean something''s wrong with the relationship.', 'Not asking for alone time to avoid seeming distant can build resentment instead. Naming the need for space plainly is usually easier than pulling away silently.'),
  ('expression', 48, 'Feeling unseen and staying silent about it rarely fixes itself.', 'Hoping someone will eventually notice your effort without you saying anything puts a lot of faith in guesswork. It''s fair to just name what you''d like acknowledged.'),
  ('expression', 49, 'A boundary you never state is a boundary no one can respect.', 'Assuming people should just know your limits at work often means those limits get crossed repeatedly. Stating them plainly, even briefly, changes that.'),
  ('expression', 50, 'Asking ''are we okay'' is usually less scary than not knowing.', 'Avoiding the question to dodge an uncomfortable answer can leave you circling the uncertainty far longer than the actual conversation would take.'),
  ('expression', 51, 'A mistake named early is smaller than a mistake found later.', 'Delaying an admission to avoid immediate discomfort often makes the eventual conversation harder, not easier. Most mistakes shrink the sooner they''re named.'),
  ('expression', 52, 'Strength doesn''t require hiding what''s actually happening inside.', 'Performing steadiness while quietly struggling can look like strength from the outside, but it often just delays getting support that would actually help.'),
  ('expression', 53, 'Needing reassurance sometimes is normal, not needy.', 'Holding back a request for reassurance to avoid seeming anxious can leave you sitting with worry longer than necessary. A short, direct ask is usually enough.'),
  ('expression', 54, 'Good news doesn''t need to be minimized to be believable.', 'Playing down something exciting to avoid seeming like you''re bragging can quietly train you to shrink your own good moments. It''s okay to just be glad, out loud.'),
  ('expression', 55, 'Unspoken forgiveness still leaves the other person guessing.', 'Forgiving someone internally without ever saying so can leave them unsure where things stand. A short, clear statement can close something quietly left open.'),
  ('expression', 56, 'Resentment is often just an unspoken request, worn down over time.', 'Staying silent about what''s bothering you can slowly turn into resentment, which is harder to resolve than the original issue would have been.'),
  ('expression', 57, 'Naming what isn''t working is the first step to changing it.', 'Staying quiet about something that isn''t working can make it feel permanent by default. Saying it plainly opens the door to actually adjusting it.'),
  ('expression', 58, 'A goodbye is allowed to look exactly as sad as it feels.', 'Keeping a composed face during a hard goodbye can feel necessary, but it''s also fine to let the sadness show, it doesn''t make the moment weaker, just more honest.'),
  ('expression', 59, 'Feeling hurt by criticism doesn''t mean the criticism was wrong.', 'Pretending feedback didn''t sting can keep you from processing it honestly. It''s possible to both accept the point and admit it hurt to hear.'),
  ('expression', 60, 'The conversation you''re avoiding is often shorter than the discomfort of avoiding it.', 'Postponing an honest conversation can feel like avoiding pain, but the anticipation usually costs more than the conversation itself would.'),
  ('awareness', 1, 'The conversation is over, but your mind kept the meeting going.', 'Replaying what you said after a conversation ends rarely changes what happened. If something''s still bothering you, the more useful move is usually addressing it, not replaying it.'),
  ('awareness', 2, 'Rehearsed conversations rarely happen the way you rehearsed them.', 'Running through exact scripts before a hard conversation can help you organize your thoughts, but expecting the real thing to follow the script often adds pressure instead of ease.'),
  ('awareness', 3, 'A text message isn''t a puzzle that needs solving.', 'Analyzing wording, punctuation, and timing for hidden meaning usually produces more theories than answers. Most short messages mean exactly what they say.'),
  ('awareness', 4, 'A decision already made doesn''t need to be relitigated nightly.', 'Once a reasonable decision is made, revisiting it repeatedly rarely improves it, it mostly just adds stress on top of a choice you''ve already stood by.'),
  ('awareness', 5, 'The worst-case version in your head is rarely the one that shows up.', 'Imagining every way something could go wrong feels like preparation, but most outcomes land somewhere far more ordinary than the scenarios your mind rehearses.'),
  ('awareness', 6, 'Rereading an email five times doesn''t make it more correct, just more delayed.', 'There''s a point where extra review stops improving the message and starts just postponing sending it. Most emails are fine well before the fifth read.'),
  ('awareness', 7, 'Buyer''s remorse is a feeling, not necessarily a fact about the purchase.', 'Second-guessing a reasonable purchase after the fact is common and doesn''t always mean it was the wrong call, sometimes it''s just the mind looking for something to examine.'),
  ('awareness', 8, 'A tone of voice can be read a dozen ways, and most of them are wrong.', 'Overanalyzing how someone sounded assumes you have full information about their mood, which you rarely do. Asking directly usually settles it faster than guessing.'),
  ('awareness', 9, 'Nighttime ''what ifs'' rarely lead anywhere productive.', 'Late-night worry loops tend to generate more questions than answers. Writing the thought down for tomorrow can be more useful than trying to resolve it at midnight.'),
  ('awareness', 10, 'A compliment doesn''t usually come with a hidden agenda.', 'Searching for a second meaning behind a kind comment often says more about your own uncertainty than about the person who said it. Most compliments are just compliments.'),
  ('awareness', 11, 'Two good options can both stay good options without a perfect answer.', 'Endlessly comparing two reasonable choices can create the illusion that one is secretly better. Often, either choice would have worked out fine.'),
  ('awareness', 12, 'The fifth draft of a message isn''t always clearer than the first.', 'Rewriting the same message many times can polish away the honesty that made the first version worth sending. Sometimes the early draft was the truest one.'),
  ('awareness', 13, 'A friend''s silence has more explanations than the one you''re assuming.', 'Not hearing back quickly gets filled in with theories, and the theories are rarely as boring as the real explanation, which is often just a busy day.'),
  ('awareness', 14, 'One mistake at work doesn''t erase the rest of your track record.', 'Spiraling over a single error can make it feel much bigger than it is. Most workplace mistakes are forgotten by others far sooner than by the person who made them.'),
  ('awareness', 15, 'Deciding whether to bring something up can take longer than actually bringing it up.', 'The mental rehearsal of a hard topic often takes more energy than the real conversation would. At some point, saying it becomes easier than continuing to plan it.'),
  ('awareness', 16, 'Predicting a conversation doesn''t make the real one go that way.', 'Scripting how someone will respond before you''ve even spoken to them sets up expectations the real conversation rarely follows. It''s usually more useful to just start it.'),
  ('awareness', 17, 'No one is studying your facial expressions as closely as you are.', 'Worrying about how your face looked in a meeting assumes everyone was watching that closely. Most people are focused on their own moment, not yours.'),
  ('awareness', 18, 'An old decision doesn''t need a permanent verdict.', 'Revisiting a past choice again and again rarely produces new information, it just repeats the same judgment with slightly different words each time.'),
  ('awareness', 19, 'Most people forget the small social moment you''re still replaying.', 'A slightly awkward comment or pause usually leaves everyone else''s memory within the hour. It tends to stay longest in the mind of the person who said it.'),
  ('awareness', 20, 'Planning can quietly become a way to avoid starting.', 'There''s a point where more planning stops adding clarity and starts just delaying the first real step. Sometimes starting teaches you more than another round of planning would.'),
  ('awareness', 21, 'What you wear rarely gets the scrutiny you''re imagining.', 'Overthinking an outfit assumes other people are paying close attention to your choices. Most people are thinking about their own outfit, not analyzing yours.'),
  ('awareness', 22, 'Not every day needs a full nightly review.', 'Replaying every decision before bed can turn rest time into another round of self-assessment. Some days are fine to just end, without a full audit.'),
  ('awareness', 23, 'A slow reply is rarely a verdict on the relationship.', 'Assuming a delayed response means something is wrong fills a gap with worry. Often it just means the other person was busy, tired, or hadn''t opened the message yet.'),
  ('awareness', 24, 'A hypothetical only feels real because you keep rehearsing it.', 'Getting lost in scenarios that haven''t happened can make them feel almost certain. Most of what gets imagined this way never actually occurs.'),
  ('awareness', 25, 'An apology doesn''t need a passing grade to count.', 'Wondering if an apology was ''enough'' can turn a genuine moment into another thing to overthink. If it was honest, it was probably enough.'),
  ('awareness', 26, 'A worry that keeps circling without landing anywhere isn''t solving anything.', 'Some thoughts loop not because they''re unresolved, but because they were never solvable in the first place, they just need to be set down instead of finished.'),
  ('awareness', 27, 'Feedback from weeks ago doesn''t need to keep being reprocessed.', 'Returning to old feedback long after it was given can turn a helpful comment into a lingering judgment. At some point, it''s fair to let it finish doing its job.'),
  ('awareness', 28, 'Rehearsing a conversation you''ll likely never have costs real energy.', 'Some imagined conversations exist only to process a feeling, not to actually happen. It can help to notice when a rehearsal is really just processing in disguise.'),
  ('awareness', 29, 'A joke that didn''t land isn''t usually remembered as long as you think.', 'Replaying a joke that fell flat tends to matter far more to the person who told it than to anyone else in the room, who has likely already moved on.'),
  ('awareness', 30, 'Not every decision deserves the same amount of deliberation.', 'Spending a long time deciding something low-stakes can borrow energy from decisions that actually matter more. Some choices are fine to make quickly.'),
  ('awareness', 31, 'Most everyday interactions aren''t tracked as closely by others as they are by you.', 'Wondering whether you offended someone in a routine exchange usually assumes more attention was paid than actually was. A quick check-in settles it faster than guessing.'),
  ('awareness', 32, 'An old embarrassing moment doesn''t get less over with the more it''s replayed.', 'Revisiting a memory from years ago rarely changes it, it just keeps the discomfort fresh. It''s allowed to just be a memory instead of a recurring event.'),
  ('awareness', 33, 'A decision that''s already been made doesn''t need continued approval.', 'Once a choice has been acted on, ongoing debate about whether it was right mostly just adds doubt, not new information.'),
  ('awareness', 34, 'Not every action needs every outcome mapped out first.', 'Trying to predict every possible result before acting can stall movement entirely. Some outcomes only become clear once something is actually tried.'),
  ('awareness', 35, 'How others see your success is mostly outside your control anyway.', 'Spending energy managing other people''s perception of your achievements takes focus away from the achievement itself, which is the part you actually shaped.'),
  ('awareness', 36, '''Should I have said that'' loops rarely arrive at a final answer.', 'Replaying whether a comment was the right one to make can go on indefinitely because there''s no verdict waiting at the end, just another replay.'),
  ('awareness', 37, 'Body language in a meeting can mean fifty different things.', 'Reading crossed arms or a flat expression as a clear signal assumes a level of certainty that isn''t really there. It''s often just how someone happens to be sitting.'),
  ('awareness', 38, 'Deciding whether to send it has already cost more energy than sending it would.', 'Endless deliberation about whether to reach out can take more out of you than the actual message would. Sending it usually resolves more than waiting does.'),
  ('awareness', 39, 'A typo in an email is rarely remembered by the person who received it.', 'A small error that feels glaring to you is usually invisible or instantly forgotten by the reader, who''s typically focused on the content, not the formatting.'),
  ('awareness', 40, 'Plans weeks away don''t need to be finalized in your head tonight.', 'Running through details for something far in the future can feel productive, but most of it will need to be revisited anyway once it''s actually closer.'),
  ('awareness', 41, 'Rehashing an old argument doesn''t change how it ended.', 'Replaying a past disagreement with better comebacks doesn''t rewrite the outcome, it just keeps you in a conversation that''s already over.'),
  ('awareness', 42, 'Some decisions don''t have a ''perfect'' option waiting to be found.', 'Searching for the flawless choice among reasonable options can stall a decision indefinitely. Sometimes ''good enough and made'' beats ''perfect and still undecided.'''),
  ('awareness', 43, 'Someone else''s plan isn''t a hidden standard yours has to match.', 'Comparing your approach to how someone else might have done it assumes there''s one right way. Different plans can both work for different people.'),
  ('awareness', 44, 'A feeling doesn''t always need a fully solved explanation before it''s allowed.', 'Trying to fully explain why you feel a certain way before accepting it can delay dealing with it. Some feelings are worth acting on before they''re fully understood.'),
  ('awareness', 45, 'A reversible decision doesn''t need irreversible amounts of thought.', 'Spending huge energy on a choice you could easily change later borrows weight from decisions that actually are permanent.'),
  ('awareness', 46, 'Predicting how a relationship ends doesn''t tell you anything about how it''s going now.', 'Running future scenarios about an ending can pull attention away from what''s actually happening in the relationship today, which is the part you can respond to.'),
  ('awareness', 47, 'People usually mean what they said, not a hidden version of it.', 'Assuming there''s a deeper, unspoken meaning behind someone''s words often creates more confusion than the words themselves. Taking things at face value first is usually more accurate.'),
  ('awareness', 48, 'A decision with no wrong answer doesn''t need to feel this heavy.', 'When every option is genuinely fine, the difficulty isn''t really about which to choose, it''s about the discomfort of choosing at all. That''s worth noticing on its own.'),
  ('awareness', 49, 'Overthinking your overthinking just adds another layer to unwind.', 'Noticing you''re stuck in a thought loop and then worrying about being stuck in it can double the spiral. Sometimes the move is just to name it and let it be.'),
  ('awareness', 50, 'Wondering if you''re overreacting is sometimes its own kind of overreacting.', 'Questioning the validity of your own reaction can become another loop on top of the original feeling. Reactions don''t need to pass a fairness test before they''re allowed.'),
  ('awareness', 51, 'An old issue doesn''t need a perfect opening to be brought up.', 'Waiting for the exact right moment to raise something can turn into waiting indefinitely. A slightly imperfect moment is usually still better than no moment at all.'),
  ('awareness', 52, 'Doubt after committing doesn''t mean the commitment was wrong.', 'Second-guessing a decision after you''ve already acted on it is common and doesn''t necessarily mean anything went wrong, sometimes it''s just the mind catching up.'),
  ('awareness', 53, 'A conversation that went fine doesn''t need a post-mortem.', 'Replaying an interaction that actually went well can still trigger analysis out of habit. It''s worth noticing when the review is happening on something that didn''t need one.'),
  ('awareness', 54, 'A mistake nobody noticed doesn''t need your ongoing attention either.', 'Continuing to dwell on an error that had no real consequence keeps a private cost going for something that, to everyone else, already passed unnoticed.'),
  ('awareness', 55, 'Planning for scenarios that likely won''t happen still uses real energy now.', 'Preparing extensively for unlikely outcomes can feel responsible, but it borrows focus from what''s actually in front of you today.'),
  ('awareness', 56, 'A plan changing at the last minute doesn''t always have a deeper reason.', 'Searching for meaning behind a shifted plan often assumes intention where there was just logistics. Most last-minute changes are exactly what they look like.'),
  ('awareness', 57, 'Looping on a relationship status in your head doesn''t move it forward.', 'Replaying the same uncertainty about where things stand tends to produce more anxiety than clarity. A direct conversation usually answers what the loop can''t.'),
  ('awareness', 58, 'Silence doesn''t automatically mean something is wrong.', 'Reading a quiet stretch as a sign of trouble fills an information gap with worry. Often silence is just silence, without a hidden message attached.'),
  ('awareness', 59, 'Pros and cons lists have a point of diminishing returns.', 'Weighing options well past the point of new information doesn''t sharpen the decision, it usually just adds more time spent deciding without added clarity.'),
  ('awareness', 60, 'A decision made under pressure at the deadline is still a decision, not a failure.', 'Overthinking until the moment to decide has passed can force a choice by default. Choosing at the last minute isn''t ideal, but it''s still a choice, not a verdict on your character.'),
  ('momentum', 1, 'Wanting a different career and not taking the first step are two separate things.', 'It''s possible to be genuinely unhappy with a career and still not act, not because you don''t want change, but because the first move feels disproportionately large compared to the rest.'),
  ('momentum', 2, 'Knowing what to do isn''t the same as having started doing it.', 'Clarity about the next step doesn''t automatically produce motion. The gap between knowing and starting is often just about lowering the size of the first action, not finding more clarity.'),
  ('momentum', 3, 'A job you meant to leave months ago is still just a job, not a life sentence.', 'Staying past the point you wanted to leave can happen quietly, one ''not yet'' at a time. The exit is usually still available, even if the moment to take it passed unnoticed.'),
  ('momentum', 4, 'A routine can feel busy and still not be moving you anywhere.', 'Repeating the same days can create a sense of motion without any actual progress underneath it. Busy and stuck aren''t opposites, they can happen at the same time.'),
  ('momentum', 5, 'Staying in a relationship you''ve quietly decided to leave delays the decision, it doesn''t undo it.', 'Once the decision has really been made internally, staying doesn''t reverse it, it just postpones acting on something that''s already been decided.'),
  ('momentum', 6, 'An indefinitely postponed decision is still a decision, just an invisible one.', 'Not choosing feels like avoiding the risk of a decision, but it''s actually still a choice, usually the choice to keep things exactly as they are.'),
  ('momentum', 7, 'Everyone''s timeline looks faster from the outside than it feels on the inside.', 'Comparing your pace to what you see of other people''s progress rarely accounts for the slow, invisible parts of their process that you never actually witnessed.'),
  ('momentum', 8, 'The first page doesn''t have to be good, it just has to exist.', 'Waiting to start until the first attempt feels right can delay a project indefinitely. Most first pages are meant to be rewritten, not perfect.'),
  ('momentum', 9, 'Comfort and desire aren''t the same reason to stay somewhere.', 'Staying in a familiar situation because it''s easy is different from staying because you actually want to be there. It''s worth noticing which one is actually driving the decision.'),
  ('momentum', 10, 'Knowing a habit isn''t working is the easy part, changing the routine around it is the harder one.', 'Awareness that something isn''t working doesn''t automatically dismantle it. The habit is usually held up by a routine, not just a decision, so the routine is what needs to shift.'),
  ('momentum', 11, 'The message you keep meaning to send isn''t getting easier to send by waiting.', 'Putting off reaching out to someone often makes the eventual message feel more loaded, not less. A short, imperfect message now is usually easier than the perfect one you''re waiting to write.'),
  ('momentum', 12, '''Should'' is a poor measure of where you actually are.', 'Comparing your life to where you think you ''should'' be by now uses an arbitrary timeline that was never guaranteed to apply to you in the first place.'),
  ('momentum', 13, 'Not asking for the raise doesn''t protect you from an answer, it just delays finding out.', 'Avoiding the ask can feel like avoiding rejection, but it also removes any chance of a yes. The uncertainty of asking is usually shorter-lived than the uncertainty of not knowing.'),
  ('momentum', 14, 'A big desire for change doesn''t need a big announcement to start.', 'Waiting until you can articulate the whole plan before mentioning it out loud can keep the idea stuck in private. Saying even a rough version out loud is often the first real step.'),
  ('momentum', 15, 'The ''right time'' is rarely a specific date, it''s usually just a decision dressed up as a deadline.', 'Waiting for perfect conditions before starting can turn into an indefinite wait, since most ''right times'' are actually just moments someone decided to begin anyway.'),
  ('momentum', 16, 'Staying because moving feels overwhelming doesn''t make the moving feel smaller later.', 'Postponing a big change to avoid the overwhelm of it doesn''t reduce the overwhelm, it just delays when you''ll have to face it, usually with less time to prepare.'),
  ('momentum', 17, 'Choosing neither path is still a choice, just one that gets made by default.', 'Standing between two options without picking either can feel like keeping your options open, but time spent undecided is still time spent, just without a direction.'),
  ('momentum', 18, 'The beginner version of learning something new doesn''t need to look impressive.', 'Waiting to start learning until you feel ready assumes readiness comes before the first attempt, when usually it''s the attempts themselves that build it.'),
  ('momentum', 19, 'Staying busy can be one of the most convincing ways to avoid the thing that actually matters.', 'Filling time with tasks can create a feeling of productivity while quietly avoiding the one thing that would actually move you forward.'),
  ('momentum', 20, 'A goal that only exists in your head is easier to postpone than one written down.', 'Vague intentions are simple to keep delaying because there''s no fixed version to hold yourself to. Writing it down, even roughly, makes it harder to quietly abandon.'),
  ('momentum', 21, 'You''re allowed to have outgrown a version of yourself you''re still acting like.', 'Continuing to live by old assumptions about who you are can keep you stuck in patterns that no longer fit, even after the person underneath them has changed.'),
  ('momentum', 22, 'The conversation you''re avoiding might be the exact thing unsticking the situation.', 'A single honest conversation can sometimes resolve what months of waiting and hoping haven''t. Avoiding it protects the moment, but it usually extends the stuck feeling.'),
  ('momentum', 23, 'Ending a habit without changing what surrounds it usually just brings the habit back.', 'Willpower alone rarely outlasts a routine built to support the old habit. Changing the environment around it tends to matter more than the decision to stop.'),
  ('momentum', 24, 'Planning mode can quietly become its own form of staying stuck.', 'Continuing to refine a plan can feel productive while functioning as a socially acceptable way to avoid actually doing anything.'),
  ('momentum', 25, 'A problem that keeps resurfacing is pointing at something underneath it.', 'When the same issue keeps coming back in different forms, it''s often a sign the real cause is one step deeper than the version you''ve been trying to fix.'),
  ('momentum', 26, '''More'' is hard to move toward when it''s never been defined.', 'Wanting more without specifying what that actually means can leave you unable to recognize progress even when it happens. A vague goal is hard to walk toward.'),
  ('momentum', 27, 'Comfort zones are comfortable, not necessarily where you''re supposed to stay.', 'Staying somewhere because leaving feels risky is a reasonable instinct, but it''s worth separating the actual risk from the discomfort of doing something unfamiliar.'),
  ('momentum', 28, 'An apology gets harder to give the longer it waits, not easier.', 'Letting time pass instead of apologizing can feel like the moment has passed too, but the apology is usually still wanted, even after a delay.'),
  ('momentum', 29, 'Too many options can feel like freedom and function like a wall.', 'Facing many reasonable choices can create paralysis instead of decisiveness. Narrowing the field, even arbitrarily, is often more useful than waiting for one option to feel obviously best.'),
  ('momentum', 30, 'Failing quietly in private is still failing, it just also adds isolation on top.', 'Avoiding a new attempt to prevent public failure often just means facing the same fear alone, without any of the support that trying in the open might have brought.'),
  ('momentum', 31, 'A different life you''re not talking about is still a life you want.', 'Keeping a desire for change entirely private can make it feel less real, even to yourself. Saying it out loud, even quietly, tends to make it more possible.'),
  ('momentum', 32, 'An unfinished project doesn''t expire, it just waits.', 'Something started long ago and set aside isn''t gone, it''s paused. Picking it back up doesn''t require starting over, just returning to where you left it.'),
  ('momentum', 33, 'No one is holding the permission you''re waiting for.', 'Waiting to feel authorized to make a change usually means waiting indefinitely, since that kind of permission rarely arrives from outside. Most people just decide and move.'),
  ('momentum', 34, 'Unfamiliar isn''t the same as unsafe.', 'Staying in the same pattern because change feels unfamiliar treats novelty itself as a threat, when it''s often just discomfort that fades with a bit of practice.'),
  ('momentum', 35, 'A fresh start doesn''t require knowing the whole new direction first.', 'Waiting to have the entire plan mapped out before beginning again can delay the start indefinitely. Most fresh starts begin with one small, undramatic decision.'),
  ('momentum', 36, 'Where you thought you''d be by now was always a guess, not a deadline.', 'Measuring your current life against an earlier prediction treats that prediction as fact, when it was really just a guess made with far less information than you have now.'),
  ('momentum', 37, 'A friendship that no longer fits doesn''t have to end all at once.', 'Leaving a relationship that''s outgrown its usefulness can happen gradually, through smaller adjustments, rather than requiring one big, dramatic conversation.'),
  ('momentum', 38, 'Staying undecided to keep every door open can quietly close all of them anyway.', 'Avoiding a choice to preserve every possibility often just means time passes without any of the possibilities being pursued.'),
  ('momentum', 39, 'A hobby that never gets time isn''t really a priority, even if it''s still a want.', 'Wanting to make space for something and never scheduling it usually means it keeps losing to whatever''s more urgent. Blocking actual time tends to matter more than intention.'),
  ('momentum', 40, 'A day that feels like a repeat is still a day where something small could shift.', 'Noticing that today feels identical to yesterday can be the first sign something needs to change, not proof that nothing ever will.'),
  ('momentum', 41, 'A hard conversation with a parent doesn''t get less hard by staying unspoken longer.', 'Avoiding a difficult family conversation can feel protective, but the discomfort usually doesn''t shrink with time, it just waits.'),
  ('momentum', 42, 'Survival mode is meant to be temporary, even when it becomes a habit.', 'Staying in crisis-response mode after the crisis has passed can keep you braced for something that''s no longer happening, using energy that could go toward rebuilding.'),
  ('momentum', 43, 'Giving up on day two doesn''t mean the habit failed, it means one attempt did.', 'A new habit that didn''t survive the first week isn''t evidence it can''t work, most habits take multiple restarts before they actually stick.'),
  ('momentum', 44, 'A first step can be made smaller instead of the goal being made smaller.', 'When the first step feels too large to take, the fix is usually to shrink the step, not to give up on the goal it was meant to start.'),
  ('momentum', 45, 'Fear of disappointing others can quietly outweigh the change you actually want.', 'Worrying about who might be let down by a change can keep you stuck in a version of life chosen more for other people''s comfort than your own.'),
  ('momentum', 46, 'Naming burnout is the first change, even before anything else shifts.', 'Staying silent about burnout while waiting for circumstances to improve on their own can extend it much longer than necessary. Naming it is often the actual first step.'),
  ('momentum', 47, 'An old passion doesn''t need to be revived all at once.', 'Reconnecting with something you used to love can start with ten minutes, not a full return. Waiting for the motivation to feel like it once did can delay it indefinitely.'),
  ('momentum', 48, 'Everything doesn''t need to be sorted before something can begin.', 'Waiting for full clarity before starting can keep a plan permanently in the waiting room. Most things get clearer once they''re actually underway, not before.'),
  ('momentum', 49, 'A situation that''s become familiar isn''t the same as one that''s become good for you.', 'Staying in something harmful out of habit can feel like stability, but familiarity and wellbeing aren''t the same thing, even when they get confused for each other.'),
  ('momentum', 50, 'One small action usually reveals more than another round of analysis.', 'More thinking about a stuck situation doesn''t always produce more clarity, sometimes only an actual small step does, since it generates real information the analysis couldn''t.'),
  ('momentum', 51, 'Asking for help getting unstuck is itself a way of getting unstuck.', 'Not asking for support can feel like managing it alone, but the request itself is often the first real movement after a long stretch of nothing changing.'),
  ('momentum', 52, 'A goal that feels far away still only needs a next step, not the whole distance at once.', 'Focusing on how far away the goal looks can obscure the much smaller, much more doable question of what the very next action would be.'),
  ('momentum', 53, 'The same choices tend to produce the same results, even when the desire for change is real.', 'Wanting change while repeating familiar decisions creates a loop that feels like effort without actually producing anything new.'),
  ('momentum', 54, '''It still sort of works'' is a low bar for staying somewhere.', 'A situation that technically functions can still be quietly costing more than it''s giving. ''It still works'' isn''t the same question as ''is this still worth it.'''),
  ('momentum', 55, 'More certainty rarely arrives before a decision, usually it arrives after one is made.', 'Waiting for enough certainty to feel confident can delay a decision indefinitely, since most certainty about a choice only builds once it''s actually been acted on.'),
  ('momentum', 56, 'Watching other people move doesn''t mean your own timing is wrong.', 'Comparing your pace to the visible progress of others rarely accounts for how much of their process happened out of view before it became visible.'),
  ('momentum', 57, 'Starting over doesn''t have to mean starting from zero on everything.', 'Treating a fresh start as all-or-nothing can make it feel too big to attempt. Most restarts only require changing a few key things, not discarding everything.'),
  ('momentum', 58, 'Staying in place can be less about the situation, more about not calling it a mistake.', 'Leaving a choice that didn''t work out can feel like admitting failure, but recognizing that something didn''t work is different from failing, it''s just information.'),
  ('momentum', 59, 'The one action you''re avoiding might be the exact one that would move things forward.', 'Wanting a specific change while consistently avoiding the one step that would actually create it usually means that step is the real work, not a detail to skip.'),
  ('momentum', 60, '''About to start'' can quietly become its own permanent status if it''s never checked.', 'Staying in a long stretch of intending to begin can start to feel like progress, even when nothing has actually moved. It''s worth noticing how long ''about to'' has really lasted.'),
  ('direction', 1, 'Not knowing what you want is its own kind of information.', 'The absence of a clear want doesn''t mean something''s wrong with you, it can just mean the question needs more time, or a different question altogether.'),
  ('direction', 2, 'A directionless feeling about your career doesn''t mean you''ve made the wrong choices.', 'Not having a clear next step doesn''t erase the ones you''ve already taken. It''s possible to feel lost and still be exactly where useful experience is being built.'),
  ('direction', 3, 'Not knowing if you want to stay or leave is a real answer, not a failure to decide.', 'Uncertainty about a relationship isn''t the same as indecisiveness, it can mean the situation genuinely has real reasons pulling in both directions.'),
  ('direction', 4, 'Wanting change without knowing what kind is still worth paying attention to.', 'A vague pull toward something different doesn''t need to be fully defined before it''s taken seriously. Sometimes the shape becomes clear only after you start moving.'),
  ('direction', 5, 'A 5-year plan is a guess dressed up as a requirement.', 'Feeling behind for not having a clear long-term plan assumes everyone else actually has one figured out, when most people are improvising further out than they let on.'),
  ('direction', 6, 'Not knowing if you want kids is allowed to stay unresolved for a while.', 'Some decisions don''t arrive on a schedule. Sitting with genuine uncertainty is different from avoiding the question, and it doesn''t need to be rushed.'),
  ('direction', 7, 'A want that can''t be named yet is still a real want.', 'Feeling like something needs to change without being able to say exactly what doesn''t mean the feeling is invalid, it might just need more space to take shape.'),
  ('direction', 8, 'A path chosen because it''s expected can quietly stop feeling like a choice at all.', 'It''s worth periodically checking whether a direction is still yours, or whether it became more of an inherited default somewhere along the way.'),
  ('direction', 9, 'Not knowing what makes you happy is common, even later in life.', 'Happiness isn''t always self-evident, and figuring it out can take active experimenting rather than just quiet reflection.'),
  ('direction', 10, 'A goal borrowed from someone else can still feel like ambition.', 'It''s worth checking whether a goal excites you on its own, or whether it mostly excites you because of who else values it.'),
  ('direction', 11, 'Freedom without direction can feel surprisingly disorienting.', 'Having fewer constraints doesn''t automatically produce clarity about what to do with the space, sometimes it takes longer to fill than expected, and that''s normal.'),
  ('direction', 12, 'Not knowing if you want to move might mean both options genuinely have something.', 'Weighing a move for a long time can reflect a real, complicated set of trade-offs rather than an inability to choose.'),
  ('direction', 13, 'Changing interests aren''t proof you can''t commit to anything.', 'A shifting set of interests over time is often just growth, not evidence of flakiness. What holds your attention now doesn''t have to match what held it a year ago.'),
  ('direction', 14, 'Success without a personal definition tends to borrow someone else''s.', 'Chasing a version of success that was never explicitly chosen can leave you achieving things that don''t actually feel like wins once you get there.'),
  ('direction', 15, 'Wanting both stability and adventure isn''t a contradiction, it''s just two needs.', 'Most people want some mix of security and novelty. The discomfort usually isn''t about wanting both, it''s about assuming you have to pick only one.'),
  ('direction', 16, 'Wanting out of a career and needing a break can look identical from the inside.', 'Burnout can masquerade as a desire for total change. It''s worth checking whether rest would shift the feeling before assuming the whole path is wrong.'),
  ('direction', 17, 'Not being sure you actually want something is worth listening to, even mid-decision.', 'Hesitation before a big decision isn''t always fear of commitment, sometimes it''s useful information that the want isn''t as solid as it first seemed.'),
  ('direction', 18, 'What you''d choose without fear in the room is worth asking, even if fear stays in the room.', 'Imagining the decision without the fear attached can reveal what''s actually wanted underneath, even if the fear itself doesn''t fully go away.'),
  ('direction', 19, 'Wanting someone to just confirm your choice isn''t the same as not having one.', 'Seeking outside validation for a decision you''re leaning toward is common, and it doesn''t mean the underlying preference isn''t already yours.'),
  ('direction', 20, 'A major life path doesn''t have to be permanent to be worth picking.', 'Treating an early choice as a lifelong sentence can make it feel impossibly heavy. Most paths bend, adjust, or change entirely later on.'),
  ('direction', 21, 'Ambition that was never questioned might not be fully yours yet.', 'It''s worth occasionally asking whether a driving goal reflects what you actually want, or a version of achievement absorbed early and never revisited.'),
  ('direction', 22, 'Wanting everything and nothing at once can just mean the options haven''t been narrowed yet.', 'That scattered feeling often isn''t about a lack of desire, it''s about too many undifferentiated possibilities competing for the same attention.'),
  ('direction', 23, 'Not being sure if you want more or less responsibility is a real question, not a lack of ambition.', 'Wanting to step back at some point isn''t automatically a step down, it can just reflect a shift in what actually matters to you right now.'),
  ('direction', 24, 'Free time without a plan can feel oddly uncomfortable at first.', 'Unstructured time sometimes needs to be sat with before it becomes clear what to do with it. That discomfort tends to fade with a bit of practice.'),
  ('direction', 25, 'The relationship you want doesn''t have to match the one you''re picturing exactly.', 'Comparing a real relationship to an idealized version can obscure what''s actually working. It''s worth separating genuine mismatches from unmet fantasy.'),
  ('direction', 26, 'Purpose doesn''t usually arrive fully formed, it tends to get built.', 'Waiting to feel a clear sense of purpose before acting can delay things indefinitely. For most people, purpose becomes clearer through doing, not before it.'),
  ('direction', 27, 'A years-old dream is allowed to be re-evaluated, not just pursued out of loyalty.', 'Holding onto an old goal because you''ve always had it can keep you moving toward something that no longer fits who you''ve become.'),
  ('direction', 28, 'Two very different paths can both be genuinely good, without one being the ''real'' answer.', 'The discomfort of choosing between two solid options isn''t a sign you''re missing information, sometimes it''s just what a real decision feels like.'),
  ('direction', 29, 'What you enjoy and what you think you should enjoy aren''t always the same thing.', 'It''s worth separating genuine preference from inherited ideas about what a good hobby, job, or lifestyle is supposed to look like.'),
  ('direction', 30, 'Wanting a change from routine doesn''t require already knowing the destination.', 'The pull to shake something up is valid on its own, even before there''s a clear plan for what comes next.'),
  ('direction', 31, 'A goal set years ago doesn''t have to keep being pursued out of consistency.', 'Continuing to chase an old target can happen more out of momentum than actual current desire. It''s fair to check whether it still fits.'),
  ('direction', 32, 'A goal inherited from family expectations can be quietly mistaken for your own.', 'Ambitions absorbed early in life can feel completely personal without ever having been actively chosen. It''s worth re-examining where they came from.'),
  ('direction', 33, 'Wanting less can be growth, not giving up.', 'Scaling back a goal or ambition is sometimes read as failure, but it can just as easily reflect a more accurate sense of what actually matters to you.'),
  ('direction', 34, 'Not knowing what qualities matter in a partner is common, even after wanting one for a while.', 'Clarity about what you actually need in a relationship often comes from experience, not from deciding it in advance.'),
  ('direction', 35, 'Multiple good options don''t need to be ranked perfectly to choose one.', 'Struggling to prioritize between several valid paths doesn''t mean there''s a hidden right answer, sometimes any reasonable choice moves things forward.'),
  ('direction', 36, 'A hobby doesn''t need to be a passion to be worth keeping.', 'Not every activity has to carry deep meaning to be worthwhile. Something can simply be enjoyable without needing to justify itself as a calling.'),
  ('direction', 37, 'Wanting more solitude doesn''t mean something''s wrong with your social life.', 'Needs shift over time. Wanting more alone time at a given point isn''t a rejection of people, it can just be what feels right for now.'),
  ('direction', 38, 'Recognition and the thing it''s attached to aren''t always the same want.', 'It''s worth separating whether you want the achievement itself, or the acknowledgment that tends to come with it. They don''t always point the same direction.'),
  ('direction', 39, 'A changed friendship doesn''t have to be kept or ended, it can just be reconsidered.', 'Relationships evolve, and it''s fair to ask whether one still fits without treating the question as a verdict that has to be answered immediately.'),
  ('direction', 40, 'Other people looking certain doesn''t mean they actually are.', 'Assuming everyone else has clarity about what they want, based on how confident they appear, usually overestimates how settled most people actually feel.'),
  ('direction', 41, 'An ideal day is a useful question precisely because most people haven''t actually asked it.', 'Describing a genuinely good ordinary day, in detail, often reveals more about real priorities than abstract goal-setting does.'),
  ('direction', 42, 'Wanting to travel without a clear reason is still a real want.', 'Not having a fully articulated ''why'' for wanting to travel doesn''t make the desire less legitimate, some wants make sense in hindsight, not in advance.'),
  ('direction', 43, 'A career change might be about the role, or about something the role represents.', 'It''s worth separating whether the dissatisfaction is with the specific job, or with a broader need for change that the job happens to be carrying.'),
  ('direction', 44, 'Being torn between two futures doesn''t mean one of them is wrong.', 'Both versions of a future can be genuinely appealing for real reasons. The difficulty of choosing doesn''t mean the options are actually unequal.'),
  ('direction', 45, 'An old goal is allowed to be updated as you change, not just kept or discarded.', 'A goal set at an earlier point doesn''t have to be abandoned outright if it no longer fully fits, it can also just be adjusted.'),
  ('direction', 46, 'Naming a want doesn''t obligate you to act on it immediately.', 'Avoiding naming a desire to keep it from feeling too real can also keep it permanently vague. Naming it is separate from deciding what to do about it.'),
  ('direction', 47, 'Wanting something aspirational doesn''t make it unrealistic, it just makes it unstarted.', 'A goal that feels far outside your current life isn''t automatically unreasonable, it just hasn''t had a first step taken toward it yet.'),
  ('direction', 48, 'What would be ''enough'' is worth defining specifically, not left as a moving target.', 'Without a clear sense of what enough actually looks like, almost any amount of success, money, or achievement can keep feeling insufficient.'),
  ('direction', 49, 'Wanting closeness and independence can both be true in the same season.', 'Needing both connection and space isn''t contradictory, it''s common, and the balance between them can shift without anything being wrong.'),
  ('direction', 50, 'Wanting someone else to just decide for you is a real, common feeling, not a character flaw.', 'The wish to hand a decision to someone else usually comes from decision fatigue or fear of getting it wrong, not from actually lacking a preference.'),
  ('direction', 51, 'Ambition and contentment don''t have to be competing goals.', 'Wanting to keep growing and wanting to feel at peace with where you are can coexist, even though they can pull in opposite directions at times.'),
  ('direction', 52, 'What you''d choose with no one watching is often closer to what you actually want.', 'Removing the audience from a decision, even just hypothetically, can help separate genuine preference from the version shaped by other people''s expectations.'),
  ('direction', 53, 'Some decisions are more about avoiding something than actually wanting the alternative.', 'It''s worth checking whether a choice is driven by genuine desire or mainly by a wish to escape something uncomfortable in the current situation.'),
  ('direction', 54, 'Wanting more money without a clear purpose for it can leave the goal feeling hollow once reached.', 'Money is often a means to something more specific, security, freedom, options, that''s worth naming directly instead of treating the number as the goal.'),
  ('direction', 55, 'Quitting something can be giving up or listening to yourself, and it isn''t always obvious which.', 'Both interpretations are possible for the same decision. It''s worth examining the reasoning honestly rather than assuming quitting is automatically weakness.'),
  ('direction', 56, 'A ''want'' that''s never been questioned might really just be a habit.', 'Some long-held preferences persist mostly out of routine rather than active desire. It''s worth occasionally asking whether they still hold up.'),
  ('direction', 57, 'Never having been asked what you want doesn''t mean you don''t have an answer.', 'If no one has ever really asked, the question can feel unfamiliar to answer, not because the want isn''t there, but because it''s never been exercised.'),
  ('direction', 58, 'Wanting to feel excited again is itself a want worth taking seriously.', 'Missing a past sense of enthusiasm is common, and it''s a legitimate starting point, even without yet knowing what the next exciting thing will be.'),
  ('direction', 59, 'Staying the course can be loyalty to a goal, or fear of what changing it would mean.', 'It''s worth distinguishing genuine commitment to a path from simply not wanting to face the discomfort of reconsidering it.'),
  ('direction', 60, 'Clarity doesn''t come with a guaranteed arrival date.', 'Feeling like you should have figured this out by now assumes there''s a normal timeline for certainty, when for most people, it arrives unevenly, if at all.'),
  ('steadiness', 1, 'Financial stress has a way of making everything else feel shaky too.', 'Money worries don''t stay contained, they tend to color how stable other areas of life feel, even ones that haven''t actually changed.'),
  ('steadiness', 2, 'A breakup can make the whole future feel uncertain, not just the relationship.', 'Losing a relationship often shakes more than the relationship itself, it can unsettle plans, routines, and a sense of what was coming next.'),
  ('steadiness', 3, 'A job loss can shake identity as much as income.', 'Work often quietly carries a sense of who you are, so losing it can destabilize more than finances, it can unsettle a whole sense of footing.'),
  ('steadiness', 4, 'Feeling unmoored in a new city is common, not a sign you made the wrong move.', 'A lack of familiar landmarks, routines, and people takes time to rebuild. The unsettled feeling usually fades as new anchors form, not before.'),
  ('steadiness', 5, 'A shifting friend group can leave you feeling less grounded even when nothing went wrong.', 'Social circles naturally change shape over time. The instability that comes with that isn''t necessarily a sign of a problem, just a transition.'),
  ('steadiness', 6, 'A health scare has a way of making everything else suddenly feel less certain.', 'Facing a real question about your health can shake assumptions about time and stability that usually go unexamined. That reaction makes sense.'),
  ('steadiness', 7, 'Big transitions are supposed to feel a little destabilizing.', 'Graduating, starting a new job, or any major shift disrupts the routines that usually hold daily life steady. The wobble is part of the process.'),
  ('steadiness', 8, 'Family conflict can make even a familiar home feel less safe.', 'Tension at home affects more than the specific disagreement, it can quietly erode the sense of home as a stable base, even temporarily.'),
  ('steadiness', 9, 'Uncertainty about a relationship''s future doesn''t mean the relationship is doomed.', 'Not knowing where things are headed can feel destabilizing on its own, separate from whether the relationship is actually in trouble.'),
  ('steadiness', 10, 'A sudden change in plans can rattle more than the plan itself.', 'An unexpected shift can shake a broader sense of control, even when the specific change is manageable. The reaction is often bigger than the event.'),
  ('steadiness', 11, 'A long-term goal that keeps shifting ground can still be worth pursuing.', 'Repeated changes in circumstances around a goal can make the whole pursuit feel unstable, without meaning the goal itself has become wrong.'),
  ('steadiness', 12, 'Losing trust in someone close can make the rest of life feel less steady too.', 'Broken trust in one relationship can quietly bleed into a wider sense of security, making even unrelated parts of life feel less certain.'),
  ('steadiness', 13, 'A diagnosis, yours or someone else''s, can shake how solid everything else feels.', 'Health news has a way of reordering priorities and revealing how much daily stability depended on assumptions that suddenly feel less certain.'),
  ('steadiness', 14, 'Company changes can make a stable job feel suddenly uncertain.', 'Layoffs or restructuring can unsettle a sense of security that felt solid a month earlier, even for people whose role isn''t directly affected.'),
  ('steadiness', 15, 'A big, irreversible decision can leave you shaky even when it was the right call.', 'Feeling destabilized after a major choice doesn''t necessarily mean it was wrong, sometimes it''s just the natural aftershock of closing off other paths.'),
  ('steadiness', 16, 'Identity shifts like becoming a parent or retiring can be disorienting even when wanted.', 'A major life change can shake your sense of self even when it''s positive and chosen, because it changes the daily structure identity used to rest on.'),
  ('steadiness', 17, 'Not having a stable home base right now doesn''t mean instability is permanent.', 'A temporary or unsettled living situation can make everything else feel less grounded, even when it''s genuinely a short-term chapter.'),
  ('steadiness', 18, 'Watching a parent age can quietly shift your sense of what''s solid.', 'A parent''s aging can unsettle assumptions that once felt fixed, prompting a kind of instability that has less to do with your own life.'),
  ('steadiness', 19, 'An unexpected end to a close friendship can shake more than that one relationship.', 'Losing a close friendship without warning can destabilize a broader sense of who you can count on, even when other relationships remain solid.'),
  ('steadiness', 20, 'Larger world events can make daily life feel less predictable, even without personal change.', 'It''s normal for a wider sense of uncertainty to seep into daily stability, even when nothing in your immediate life has actually shifted.'),
  ('steadiness', 21, 'Starting over in a new field can make you feel like a beginner again, and that''s expected.', 'Feeling shaky in unfamiliar territory doesn''t reflect a step backward, it''s usually just what learning something new from scratch actually feels like.'),
  ('steadiness', 22, 'A pattern of past instability can make even good moments feel hard to trust.', 'When things have been unstable before, calm can start to feel suspicious rather than reassuring. That wariness makes sense, even when things are steady.'),
  ('steadiness', 23, 'Financial dependence on someone else can feel precarious, even in a good relationship.', 'Relying on someone else financially can create instability that isn''t about the relationship''s health, just about the vulnerability of the arrangement.'),
  ('steadiness', 24, 'A relationship in limbo can feel more destabilizing than a clear ending would.', 'Ambiguity about where things stand often creates more unease than a defined outcome, even an unwanted one, because there''s nothing solid to plan around.'),
  ('steadiness', 25, 'Losing a routine that used to anchor your days can leave a real gap.', 'A disrupted routine removes more structure than it seems, since daily rhythms often quietly hold a sense of stability in place.'),
  ('steadiness', 26, 'Several unexpected changes landing at once can feel shakier than any one alone would.', 'It''s not unusual for a cluster of changes to feel more destabilizing together than the sum of their individual weight would suggest.'),
  ('steadiness', 27, 'A thinned-out support system can make ordinary stress feel heavier.', 'Fewer people to lean on changes how much any single difficulty weighs, even if the difficulty itself hasn''t gotten objectively bigger.'),
  ('steadiness', 28, 'Uncertainty about whether a decision was right doesn''t mean it wasn''t.', 'Second-guessing a major choice is common, and it doesn''t necessarily reflect the quality of the decision, just the discomfort of not having full information.'),
  ('steadiness', 29, 'A living situation that could change on short notice keeps a low hum of instability going.', 'Even a workable but uncertain housing situation can quietly tax a sense of security, since part of you stays braced for the change.'),
  ('steadiness', 30, 'Watching an important relationship grow distant can feel destabilizing even before anything is said.', 'A slow drift in a close relationship can unsettle things well before an actual conversation happens, since the uncertainty itself feels shaky.'),
  ('steadiness', 31, 'Not knowing what next year looks like doesn''t mean it will be bad.', 'A blank picture of the future often gets filled in with worry by default, even though ''unknown'' and ''bad'' aren''t actually the same thing.'),
  ('steadiness', 32, 'An uncertain prognosis is its own particular kind of hard, separate from the diagnosis itself.', 'Not knowing what to expect can be as destabilizing as the health issue itself, since it removes the ability to plan around a clear timeline.'),
  ('steadiness', 33, 'A big argument with someone important can leave you feeling shaky well after it ends.', 'Conflict with someone central to your life can unsettle more than the disagreement itself, touching a broader sense of whether the relationship is secure.'),
  ('steadiness', 34, 'A recent loss can make the rest of life feel less solid by comparison.', 'Grief has a way of exposing how much daily stability was resting on things that can change, which can leave unrelated areas feeling less certain.'),
  ('steadiness', 35, 'Starting a new chapter without your usual support nearby takes real adjustment.', 'A significant change without the people who usually help you through change can feel doubly destabilizing, it''s fair to name that as genuinely harder.'),
  ('steadiness', 36, 'Broken trust in a relationship you thought was solid can shake more than that one bond.', 'Discovering a relationship wasn''t as solid as assumed can unsettle a broader sense of judgment, not just trust in that specific person.'),
  ('steadiness', 37, 'A long-term plan falling apart unexpectedly doesn''t mean the planning itself was wrong.', 'Plans can fail for reasons outside your control. That doesn''t discredit the effort or judgment that went into making them in the first place.'),
  ('steadiness', 38, 'Not knowing your living situation months from now is a real source of low-grade stress.', 'Ongoing housing uncertainty keeps a background tension running, even when day-to-day life looks fine on the surface.'),
  ('steadiness', 39, 'A sudden change in a close friend''s life can ripple into your own sense of stability.', 'Big shifts in people close to you, even ones that aren''t about you directly, can still unsettle your own sense of what''s dependable.'),
  ('steadiness', 40, 'Realizing a long-held belief was wrong can shake more than the belief itself.', 'Discovering you were wrong about something significant can unsettle confidence more broadly, not just about that particular topic.'),
  ('steadiness', 41, 'A financial setback after a stretch of feeling secure can hit harder by contrast.', 'Losing a sense of security you''d gotten used to often feels sharper than never having had it, even if the numbers aren''t drastically different.'),
  ('steadiness', 42, 'Losing a role you relied on can shake your footing even when you''re still capable.', 'A changed role, even one you technically chose or expected, can still unsettle the identity you''d built around it.'),
  ('steadiness', 43, 'Watching your body change in unfamiliar ways can be quietly destabilizing.', 'Physical change, whether from age, illness, or life stage, can unsettle a sense of continuity with who you''ve always felt like.'),
  ('steadiness', 44, 'Not knowing whether to trust a new person or situation is a reasonable place to sit for a while.', 'Trust usually builds over time, so the discomfort of not yet knowing isn''t a problem to solve immediately, it''s just where things are right now.'),
  ('steadiness', 45, 'Conflicting advice from people you trust can leave you feeling more unsteady than no advice at all.', 'When trusted sources disagree, it can remove a sense of a clear path forward, adding its own layer of instability on top of the original decision.'),
  ('steadiness', 46, 'A sense that things could change any moment doesn''t mean they will.', 'Living with background uncertainty is its own kind of tiring, even when nothing concrete has actually shifted yet.'),
  ('steadiness', 47, 'Struggling to feel settled after multiple moves is common, not a personal failing.', 'Repeated relocation makes it harder for any one place to start feeling like home, since roots take consistent time that moving keeps interrupting.'),
  ('steadiness', 48, 'A shifted friend group dynamic can leave you unsure of your place, even quietly.', 'Social dynamics can shift subtly enough that nothing feels ''wrong'' exactly, just less certain, which can be its own quiet kind of unsettling.'),
  ('steadiness', 49, 'Watching a source of income become uncertain adds a particular kind of background stress.', 'Financial unpredictability tends to occupy more mental space than its actual size, since it touches a basic sense of security.'),
  ('steadiness', 50, 'A decision that affects your whole family can feel heavier than one that only affects you.', 'Shared-consequence decisions carry more weight, and feeling shaky about them reflects the actual scope of what''s being decided, not indecisiveness.'),
  ('steadiness', 51, 'Uncertainty about whether a relationship will last doesn''t mean it''s already ending.', 'Not being sure of the long-term outcome is different from evidence that things are going badly, even though the two can feel similar in the moment.'),
  ('steadiness', 52, 'One event making you question your own judgment doesn''t erase the judgment you''ve built over time.', 'A single miscalculation can shake confidence more broadly than it should, even though most decision-making track records include a mix of both.'),
  ('steadiness', 53, 'Feeling unanchored after leaving an old identity behind is part of building a new one.', 'Letting go of a long-held role or label removes a familiar reference point, and the disorientation that follows is often just part of the transition.'),
  ('steadiness', 54, 'Plans falling through don''t reflect on how solid the planning was.', 'Circumstances outside your control can dismantle even well-made plans. That doesn''t mean the groundwork or intention behind them was flawed.'),
  ('steadiness', 55, 'A shift in health that changes daily routines takes real adjustment, not just acceptance.', 'New physical limits or needs can unsettle a sense of normal life, and rebuilding routine around them is a genuine process, not a quick fix.'),
  ('steadiness', 56, 'A pending decision out of your hands can feel destabilizing just from the waiting.', 'Waiting on an outcome you can''t control removes the usual sense of agency, which can make the uncertainty feel bigger than the actual stakes.'),
  ('steadiness', 57, 'The space between an ending and a new beginning is allowed to feel shaky.', 'The middle of a transition, after one chapter closes and before the next takes shape, often feels the least solid, even though it''s a normal part of change.'),
  ('steadiness', 58, 'A recent betrayal can make it hard to trust your own read on people, not just theirs.', 'Being misjudged by someone you trusted can shake confidence in your own judgment more broadly, even when your read on most people has been accurate.'),
  ('steadiness', 59, 'A rough patch in a stable relationship doesn''t erase the stability that came before it.', 'An unexpected difficulty in an otherwise solid relationship can feel disproportionately destabilizing, without meaning the whole foundation was actually weak.'),
  ('steadiness', 60, 'A general sense that nothing feels as solid as it used to is worth naming directly.', 'A diffuse feeling of instability, without one clear cause, is still real and worth acknowledging, even when it''s harder to point to a single source.'),
  ('confidence', 1, 'Feeling like a fraud doesn''t mean you actually are one.', 'Impostor feelings tend to persist regardless of actual competence, which is part of why they''re unreliable as evidence. Doing the work is the real measure, not the feeling.'),
  ('confidence', 2, 'Doubt right after a decision is common, not proof the decision was wrong.', 'A wave of second-guessing right after committing to something is a normal reaction to closing off other options, not a reliable signal about the choice itself.'),
  ('confidence', 3, 'Luck rarely explains a result on its own.', 'Attributing success entirely to luck erases the preparation, decisions, and effort that also shaped the outcome. Both luck and skill can be true at once.'),
  ('confidence', 4, 'Your beginning was never supposed to look like someone else''s middle.', 'Comparing an early stage of your own path to a further-along stage of someone else''s sets an unfair benchmark neither of you actually met at the same point.'),
  ('confidence', 5, 'A compliment doesn''t need to be earned twice before it can be accepted.', 'Deflecting or doubting praise can become a habit that quietly disconnects you from accurate feedback about your own work.'),
  ('confidence', 6, 'Assuming you''ll eventually be ''found out'' treats a feeling as a fact.', 'The fear of being exposed as less capable usually isn''t based on actual evidence, it''s a familiar worry that tends to persist regardless of performance.'),
  ('confidence', 7, 'Not speaking up doesn''t mean your input wasn''t worth hearing.', 'Doubting whether you have standing to speak in a group often has more to do with confidence than with the actual value of what you''d say.'),
  ('confidence', 8, 'A skill built over years doesn''t need to be re-proven every time it''s used.', 'Second-guessing established competence can happen even with strong experience behind it, the doubt isn''t new information, just an old pattern resurfacing.'),
  ('confidence', 9, 'Wondering if you''re a good parent is itself often a sign that you''re paying attention.', 'The parents who worry about doing right by their kids are usually more engaged, not less capable, than the worry suggests.'),
  ('confidence', 10, 'Not all praise is just politeness, some of it is accurate.', 'Assuming kind feedback is automatically insincere discounts the possibility that people are simply telling you something true.'),
  ('confidence', 11, 'Feeling unready for a new role is common, even for people who end up doing it well.', 'Confidence in a role often develops through doing it, not before starting. Feeling unprepared at the outset doesn''t predict how it will actually go.'),
  ('confidence', 12, 'Everyone else looking more qualified is often just a trick of visibility.', 'You mostly see other people''s finished work and confident moments, not their doubts, mistakes, or learning curve, which skews the comparison.'),
  ('confidence', 13, 'A creative choice doesn''t need unanimous approval to have been the right one.', 'Doubting a decision because it wasn''t universally loved treats subjective response as an objective verdict, when creative work rarely gets one.'),
  ('confidence', 14, 'A mistake is information about one moment, not a verdict on your overall competence.', 'Treating a single error as proof you''re ''not good enough'' generalizes one data point into a much bigger conclusion than it can actually support.'),
  ('confidence', 15, 'How a conflict feels afterward isn''t always how it actually went.', 'Post-conflict self-doubt often runs hotter than the reality of the exchange. It''s worth separating the discomfort of conflict from an accurate read of it.'),
  ('confidence', 16, 'Relevant experience doesn''t stop counting just because you still feel unsure.', 'Feeling unqualified despite a real track record is a common mismatch between internal confidence and external evidence, the evidence is usually more accurate.'),
  ('confidence', 17, 'An instinct isn''t automatically wrong just because it''s being second-guessed.', 'Doubting a gut read after the fact doesn''t mean the instinct was flawed, it might just mean doubt showed up late, as it often does.'),
  ('confidence', 18, 'An opportunity earned through a process isn''t the same as one received by accident.', 'Assuming you got a role or chance by mistake discounts the actual steps, decisions, and qualifications that led there.'),
  ('confidence', 19, 'Whether you''re likeable usually isn''t decided by the moments you replay the most.', 'The interactions that trigger self-doubt about likeability are rarely representative of how you''re actually experienced by most people around you.'),
  ('confidence', 20, 'An opinion doesn''t need to be louder than others'' to be worth as much.', 'Feeling like your view matters less often reflects confidence, not the actual quality or relevance of what you have to say.'),
  ('confidence', 21, 'Wondering if you''re a good partner is a normal part of caring about the relationship.', 'The doubt itself often comes from investment, not evidence of failure. Most people who worry about this are actively trying, which counts for something.'),
  ('confidence', 22, 'Most people are focused on their own performance, not quietly grading yours.', 'Assuming harsh judgment from others usually overestimates how closely they''re actually paying attention to you specifically.'),
  ('confidence', 23, 'A choice that worked out fine doesn''t need to be relitigated as though it almost didn''t.', 'Continuing to doubt a decision after a good outcome discounts the actual result in favor of the discomfort felt while deciding.'),
  ('confidence', 24, 'Feeling behind your peers rarely accounts for the different starting points everyone had.', 'Career comparisons usually ignore differences in resources, timing, and circumstances that shaped each person''s pace differently.'),
  ('confidence', 25, 'Not feeling smart enough yet doesn''t predict whether you''ll rise to the challenge.', 'Confidence in a new challenge tends to build during the attempt, not before it, so feeling underqualified isn''t a reliable forecast.'),
  ('confidence', 26, 'Confidence in others doesn''t mean the absence of doubt, it often just means it''s hidden well.', 'Assuming other people don''t struggle with the same uncertainty gives their outward composure more credit than it usually deserves.'),
  ('confidence', 27, 'Whether work is ''actually good'' is worth checking against feedback, not just against the feeling.', 'Self-doubt about quality often runs independently of actual quality. Outside input tends to be a more reliable measure than the internal verdict alone.'),
  ('confidence', 28, 'Feeling like an outsider in a new circle usually fades faster than it feels like it will.', 'Early impostor feelings in a new social group are common and typically ease with time and familiarity, not with becoming a different person.'),
  ('confidence', 29, 'Not feeling ready for a hard situation doesn''t mean you won''t handle it.', 'Capability in a difficult moment is often discovered in the moment itself, not confirmed in advance by a feeling of readiness.'),
  ('confidence', 30, 'One failure describes one attempt, not a fixed level of ability.', 'Treating a single setback as proof of overall inability skips over everything else that''s gone right, which usually outweighs the one data point.'),
  ('confidence', 31, '''Enough'' is a moving target when it''s never been clearly defined.', 'Doubting whether you''re doing enough often has less to do with actual output and more to do with an undefined, ever-shifting standard.'),
  ('confidence', 32, 'A voice doesn''t need to be the loudest in the room to still matter in the decision.', 'Feeling unsure whether your input counts often reflects social dynamics more than the actual relevance of what you bring to the table.'),
  ('confidence', 33, 'Leadership ability is usually built through leading, not proven before it starts.', 'Doubting whether you can lead before having done much of it skips the part where most leaders develop the skill through actual experience.'),
  ('confidence', 34, 'Assuming others secretly think less of you rarely matches what they''d actually say if asked.', 'This kind of doubt tends to generate a harsher internal narrative than the outside world is actually producing about you.'),
  ('confidence', 35, 'A hard decision doesn''t need unanimous agreement to have been the right one.', 'Doubting a choice because someone disagreed with it treats disagreement as disproof, when reasonable people can differ without one being wrong.'),
  ('confidence', 36, 'Years of experience don''t disappear just because a moment feels unfamiliar.', 'Feeling inexperienced in a specific new situation doesn''t erase the broader base of skill and judgment built over time.'),
  ('confidence', 37, 'Wanting reassurance that people want you around doesn''t mean they don''t.', 'This kind of doubt often persists independent of actual evidence of being welcomed, since it runs on an internal loop rather than external feedback.'),
  ('confidence', 38, 'An achievement doesn''t stop counting just because it felt easier than expected.', 'Discounting accomplishments that came without excessive struggle assumes difficulty is what makes something legitimate, which isn''t really true.'),
  ('confidence', 39, 'How feedback felt to receive isn''t the same as how well it was actually handled.', 'A tense internal reaction to criticism doesn''t necessarily mean it showed outwardly or that it was handled poorly in the moment.'),
  ('confidence', 40, 'Constantly needing to prove yourself suggests an old standard, not a current shortfall.', 'The pressure to keep re-proving your worth often traces back to an earlier period rather than reflecting anything currently lacking.'),
  ('confidence', 41, 'Being a good friend isn''t measured only by the moments you remember imperfectly.', 'Doubt about friendship quality tends to focus on isolated missteps rather than the overall, longer pattern of the relationship.'),
  ('confidence', 42, 'An idea doesn''t need to be the loudest one to be one of the better ones.', 'Assuming your ideas matter less than others'' often reflects how confidently they were delivered, not their actual substance.'),
  ('confidence', 43, 'Judgment built over time doesn''t become unreliable just because it''s being questioned.', 'A track record of reasonable decisions is a more solid basis for trust than the temporary discomfort of doubting yourself in a specific moment.'),
  ('confidence', 44, 'Feeling out of place among experts doesn''t mean you don''t belong there.', 'Everyone in a room of experts started somewhere less certain too. Feeling behind in the moment doesn''t reflect your actual right to be there.'),
  ('confidence', 45, 'One person''s disagreement doesn''t automatically outweigh your own reasoning.', 'A decision can still be sound even when someone pushes back on it. Disagreement is information, not an automatic verdict against your choice.'),
  ('confidence', 46, 'Being unsure and being wrong aren''t the same thing.', 'Uncertainty about a decision doesn''t necessarily reflect a flaw in the decision itself, sometimes it''s just the discomfort of not having full information.'),
  ('confidence', 47, 'Improvement is often too slow to feel like improvement while it''s happening.', 'Doubting whether you''re improving at all can happen even during real progress, since gradual change is hard to notice from the inside.'),
  ('confidence', 48, 'Slow progress still counts as progress.', 'Discounting gains because they came slowly applies a standard that has little to do with whether real movement actually happened.'),
  ('confidence', 49, 'Rest and credit don''t have to be earned through exhaustion first.', 'Doubting whether you deserve to rest or be acknowledged often comes from a standard that requires overextending before either feels allowed.'),
  ('confidence', 50, 'Other people''s struggles are usually just less visible, not absent.', 'Assuming everyone else copes more easily than you usually reflects what they choose to show, not what they''re actually experiencing underneath.'),
  ('confidence', 51, 'Not feeling ready for a big change doesn''t mean you''re not capable of it.', 'Readiness for major life changes tends to build through the process itself, not fully arrive as confidence beforehand.'),
  ('confidence', 52, 'Needing outside approval to feel okay is a pattern, not a permanent requirement.', 'Relying heavily on external validation can be examined and gradually shifted, it isn''t a fixed trait, just a well-practiced habit.'),
  ('confidence', 53, 'A read on someone doesn''t need to be double-checked into oblivion to be trusted.', 'Instincts about people are often more accurate than the follow-up doubt gives them credit for, especially when based on repeated patterns.'),
  ('confidence', 54, 'Someone else''s quietness usually says more about them than about your standing with them.', 'Reading silence from others as disapproval assumes a lot about their internal state that you don''t actually have access to.'),
  ('confidence', 55, 'Wanting something ambitious doesn''t require pre-approval.', 'Doubting whether you''re allowed to want a big goal treats ambition as something needing permission, when it''s really just a preference you''re entitled to have.'),
  ('confidence', 56, 'Feeling like a beginner doesn''t erase the actual time already put in.', 'Occasional beginner-feeling moments can happen even with real experience behind them, the feeling doesn''t reset the accumulated skill.'),
  ('confidence', 57, 'How a mistake felt in the moment isn''t the same as how gracefully it was actually handled.', 'Internal panic during a mistake often doesn''t match the outward composure that others actually witnessed.'),
  ('confidence', 58, 'Your value doesn''t reset to zero on a day when performance dips.', 'Tying self-worth entirely to output makes an off day feel like a verdict on your whole value, when it''s really just one uneven day.'),
  ('confidence', 59, 'People''s fondness for you usually isn''t limited to the role you play for them.', 'Doubting whether you''d still be valued without your usual function underestimates how much of the connection is actually about you, not the role.'),
  ('confidence', 60, 'One hard week doesn''t erase a track record built over much longer.', 'A rough stretch can make self-worth feel suddenly shaky, but it''s worth weighing it against the fuller, longer pattern rather than the most recent week.'),
  ('gratitude', 1, 'The goalpost moving the instant you reach it isn''t a personal flaw, it''s a common pattern.', 'Immediately resetting expectations after hitting a goal can feel like ambition, but it can also just mean satisfaction never gets a chance to register.'),
  ('gratitude', 2, 'Good things happening and feeling unsatisfied can both be true at once.', 'Dissatisfaction doesn''t always mean something is actually missing, sometimes it reflects a habit of scanning for what''s next instead of registering what''s here.'),
  ('gratitude', 3, 'A promotion not feeling like enough on arrival doesn''t mean it wasn''t worth wanting.', 'The anticipated feeling of achievement often doesn''t match the real moment, that gap is common and doesn''t undo the value of what was earned.'),
  ('gratitude', 4, 'Never feeling caught up on work might say more about the workload than about your pace.', 'A perpetual sense of being behind can reflect an actually unsustainable amount of work rather than a personal shortfall in effort or speed.'),
  ('gratitude', 5, 'Rest doesn''t need to be earned through exhaustion to be legitimate.', 'Feeling like you haven''t done enough to deserve a break sets a bar that keeps rest perpetually out of reach, regardless of how much has actually been done.'),
  ('gratitude', 6, 'A vacation not feeling restful enough might mean rest itself needs redefining, not more vacation.', 'Expecting a trip to erase an ongoing sense of depletion can set it up to disappoint, since rest is often about ongoing patterns, not a single stretch of time.'),
  ('gratitude', 7, 'Fixating on the next goal right after achieving one skips the part where the achievement registers.', 'Moving straight to the next target without pausing on the current one can quietly erase the sense of progress achievements are supposed to provide.'),
  ('gratitude', 8, 'A home doesn''t need to be finished to be enough right now.', 'Treating a living space as perpetually unfinished can keep satisfaction indefinitely out of reach, even as the space genuinely improves over time.'),
  ('gratitude', 9, 'A compliment doesn''t need to match an imagined bigger one to count.', 'Measuring received praise against a hoped-for version can make real, genuine feedback feel like a letdown, even when it was sincerely meant.'),
  ('gratitude', 10, 'Never feeling like enough was done for someone you love often reflects care, not a shortfall.', 'This kind of doubt usually comes from how much someone matters to you, not from clear evidence that you''ve actually fallen short.'),
  ('gratitude', 11, 'A good day ending in a mental list of what''s missing skips the part where it was actually good.', 'Automatically closing out a decent day by cataloguing shortfalls can overwrite the day''s actual value with a running account of what wasn''t there.'),
  ('gratitude', 12, 'Effort and outcome don''t always move in the same proportion, that''s not a flaw in the effort.', 'Assuming hard work should always yield proportionally bigger results ignores how much of any outcome depends on factors outside your control.'),
  ('gratitude', 13, 'A good relationship can still leave room for an undefined want, without meaning something''s wrong.', 'Feeling like something is still missing in an otherwise solid relationship doesn''t necessarily point to a flaw, sometimes it''s just an unrelated need surfacing.'),
  ('gratitude', 14, 'Reaching a savings goal and immediately raising the bar means the goal was never the finish line.', 'Continuously moving a financial target can keep a sense of security perpetually out of reach, even as the actual numbers genuinely improve.'),
  ('gratitude', 15, 'Your body doesn''t need to hit a moving target to be where it should be.', 'A body that never quite meets an internal standard usually reflects an unstable standard, not an actual persistent problem with the body itself.'),
  ('gratitude', 16, 'A finished project doesn''t need to feel triumphant to actually be done.', 'Waiting for a big feeling of accomplishment before calling something complete can delay closure indefinitely, even after the real work is genuinely finished.'),
  ('gratitude', 17, 'Time with family doesn''t need to hit a specific quantity to have counted.', 'Measuring time together against an unspecified ''enough'' can make genuinely meaningful time feel insufficient by a standard that was never clearly defined.'),
  ('gratitude', 18, 'Good feedback not feeling glowing enough often says more about the standard than the feedback.', 'Discounting solid, positive feedback because it wasn''t maximally enthusiastic can filter out real, useful acknowledgment before it registers.'),
  ('gratitude', 19, 'Your best doesn''t need to look like an idealized version of your best to actually be it.', 'Comparing real effort to an imagined, flawless version of your best sets a standard that was never actually achievable in the first place.'),
  ('gratitude', 20, 'A new purchase losing its shine quickly is a well-documented pattern, not a personal failing.', 'The fading excitement of a new possession, sometimes called hedonic adaptation, happens to most people and doesn''t reflect poor judgment in the purchase.'),
  ('gratitude', 21, 'Life admin is rarely a finishable category, it''s an ongoing one.', 'Feeling perpetually behind on errands and logistics often reflects the nature of the category itself, which regenerates, rather than a personal shortfall.'),
  ('gratitude', 22, 'Gratitude and wanting more aren''t mutually exclusive.', 'Feeling thankful for what you have doesn''t have to cancel out a genuine desire for something different, both can coexist without contradiction.'),
  ('gratitude', 23, 'A milestone birthday doesn''t need a specific tally of accomplishments to have been well spent.', 'Measuring a life stage against an imagined checklist can obscure the actual, harder-to-quantify value of how the time was actually lived.'),
  ('gratitude', 24, 'Feeling behind while objectively on track usually reflects the feeling more than the track.', 'A persistent sense of falling behind, even with real evidence of progress, often says more about an internal pace-setting habit than actual standing.'),
  ('gratitude', 25, 'A weekend not including ''enough'' rarely gets defined clearly enough to actually be measured.', 'Feeling like a weekend fell short often runs on a vague, shifting standard rather than a specific, missed activity that can actually be named.'),
  ('gratitude', 26, 'Work going unnoticed even when it''s seen might be about acknowledgment style, not visibility.', 'Feeling unrecognized despite evidence that your work was seen can reflect a mismatch in how recognition is expressed, not an actual lack of it.'),
  ('gratitude', 27, 'Real preparation doesn''t need to produce a feeling of full readiness to have been enough.', 'The feeling of being unprepared can persist even after solid preparation, since readiness as a feeling and readiness as a fact don''t always sync up.'),
  ('gratitude', 28, 'A win getting overshadowed by the next problem doesn''t erase that the win happened.', 'Moving quickly from one challenge to the next can prevent a real accomplishment from getting its due, even though it genuinely occurred.'),
  ('gratitude', 29, 'Self-improvement doesn''t have a finish line built in by default, one has to be chosen.', 'Treating growth as an endless race can turn a genuinely useful practice into a source of chronic dissatisfaction, unless a stopping point is deliberately set.'),
  ('gratitude', 30, 'A clean house needing more done is sometimes just a moving standard, not an actual mess.', 'The feeling that a tidy space still needs more work can persist independent of how clean it actually is, since the standard itself keeps shifting.'),
  ('gratitude', 31, '''Good enough'' parenting is a real, sufficient standard, not a consolation prize.', 'Holding parenting to a standard higher than ''good enough'' sets an unreachable bar, since no parent, however devoted, meets a flawless version of the role.'),
  ('gratitude', 32, 'A hard conversation going imperfectly doesn''t mean it went badly.', 'Replaying a difficult conversation for flaws can obscure that most hard conversations are, by nature, imperfect, and still worthwhile.'),
  ('gratitude', 33, 'A raise mentally spent before it arrives skips the part where it actually gets to feel like more.', 'Immediately allocating a financial gain to future needs can prevent the improvement from ever registering as an actual increase in security.'),
  ('gratitude', 34, 'A social life doesn''t need a specific size to be the right one for you.', 'Comparing your social calendar to an assumed ''fuller'' standard ignores that different people genuinely thrive with different amounts of social contact.'),
  ('gratitude', 35, 'A to-do list that grows faster than it shrinks reflects an active life, not personal inefficiency.', 'An ever-expanding list is often just what an active life produces, not evidence that you''re falling behind on managing it.'),
  ('gratitude', 36, 'Creative work rarely feels fully ''ready,'' that feeling isn''t a reliable gate for sharing it.', 'Waiting for a sense of complete readiness before sharing creative work can delay it indefinitely, since that feeling rarely arrives on its own.'),
  ('gratitude', 37, 'There''s no actual finish line for ''enough'' reading, watching, or learning.', 'Measuring intellectual engagement against an undefined ''enough'' guarantees a permanent shortfall, since the category has no natural endpoint.'),
  ('gratitude', 38, 'A good workout still triggering ''not enough'' thoughts says more about the standard than the effort.', 'Post-workout dissatisfaction, even after real effort, often reflects an internal bar that keeps resetting rather than an accurate read of what was done.'),
  ('gratitude', 39, 'A gratitude list doesn''t need to be longer to be genuine.', 'Measuring thankfulness by quantity can turn a meaningful practice into another performance standard, when a shorter, honest list works just as well.'),
  ('gratitude', 40, 'A finished degree not feeling like an ending doesn''t mean the achievement wasn''t real.', 'Big milestones often don''t deliver the dramatic sense of closure expected of them, that mismatch doesn''t diminish what was actually accomplished.'),
  ('gratitude', 41, 'An apology doesn''t need to feel perfectly sufficient to have done its job.', 'Continuing to doubt whether an apology was ''enough'' can extend guilt well past the point where the actual repair work was done.'),
  ('gratitude', 42, 'A calendar that never feels right, too full or empty, might chase a standard that doesn''t exist.', 'Persistent dissatisfaction with how full a schedule is can reflect a shifting internal target rather than an actual, fixable scheduling problem.'),
  ('gratitude', 43, 'A compliment on your work getting quickly dismissed skips the chance to actually take it in.', 'Reflexively minimizing praise the moment it''s given can prevent accurate, useful feedback from actually registering as real information.'),
  ('gratitude', 44, 'Sleep not feeling like enough, even with hours checked out, might point to quality, not quantity.', 'A persistent sense of insufficient rest despite adequate hours can reflect sleep quality or stress, not necessarily a personal failure to rest properly.'),
  ('gratitude', 45, 'An explanation doesn''t need to eliminate all confusion to have been clear enough.', 'Feeling like you never explain yourself well enough can persist even when the explanation was genuinely clear, since some residual uncertainty is normal.'),
  ('gratitude', 46, 'A big purchase feeling underwhelming quickly is a common pattern, not proof it was the wrong choice.', 'The fading excitement after a significant purchase often says more about how adaptation works than about whether the decision itself was sound.'),
  ('gratitude', 47, 'Patience running out doesn''t mean it should have lasted longer than it reasonably could.', 'Expecting unlimited patience treats it as a resource without limits, when in reality even reasonable patience has an edge that gets reached sometimes.'),
  ('gratitude', 48, 'A house doesn''t need to meet an imagined guest-ready standard to actually be fine for guests.', 'The gap between how clean a home feels and how clean it needs to be for visitors is often much smaller than it seems from the inside.'),
  ('gratitude', 49, 'A good year still feeling incomplete might mean the review criteria were never clearly set.', 'Measuring a year against a vague sense of what should have happened makes it easy to overlook the concrete things that actually did.'),
  ('gratitude', 50, 'Effort in a relationship doesn''t always show results on the same timeline as it was given.', 'Relationship effort and visible results don''t move in lockstep, some effort compounds slowly, in ways that aren''t immediately obvious.'),
  ('gratitude', 51, 'A goodbye rarely feels like it included enough, no matter how much was actually said.', 'The sense that a goodbye fell short is common even after a genuinely meaningful exchange, since no amount of words fully matches the moment.'),
  ('gratitude', 52, 'A savings account that never feels like enough cushion might be chasing an unset target.', 'Without a specific, defined number for ''enough,'' a growing balance can still feel perpetually insufficient, regardless of how much it''s actually grown.'),
  ('gratitude', 53, 'Recovery from a hard time doesn''t move on a fixed schedule, even when it feels like it should.', 'Comparing your healing pace to an assumed timeline can create a false sense of falling behind, when recovery genuinely varies in speed for everyone.'),
  ('gratitude', 54, 'A compliment to someone else doesn''t need to be elaborate to be generous.', 'Second-guessing whether praise given to someone else was generous enough can undercut a genuinely kind gesture that already did what it was meant to do.'),
  ('gratitude', 55, 'A skill worth being proud of doesn''t need to be fully mastered to count as real progress.', 'Treating competence as insufficient until it becomes mastery sets a bar that keeps genuine skill from ever feeling like enough.'),
  ('gratitude', 56, 'Boundaries that were imperfectly set still count as boundaries.', 'Feeling like not enough limits were established discounts the ones that were, even if they weren''t executed as firmly as originally intended.'),
  ('gratitude', 57, 'A day off getting filled anyway means rest doesn''t feel earned, not that there''s nothing to rest.', 'Struggling to leave a day genuinely unstructured often reflects a belief that rest has to be justified, rather than an actual lack of things to recover from.'),
  ('gratitude', 58, 'Gratitude doesn''t need a bigger expression to have been real.', 'Worrying that thanks wasn''t conveyed strongly enough can turn a sincere moment into another thing to second-guess, when the sincerity was likely clear.'),
  ('gratitude', 59, 'A year without dramatic progress can still have included real, quieter movement.', 'Measuring a year only by visible milestones can miss the slower, less obvious progress that also genuinely happened.'),
  ('gratitude', 60, 'An ordinary good day not feeling like enough might just mean the bar has quietly gotten too high.', 'Some days are simply fine, without needing to be exceptional to have been worthwhile, that''s a reasonable standard on its own.'),
  ('connection', 1, 'Feeling checked out with people you love doesn''t mean you love them less.', 'Emotional distance can develop independent of how much someone actually matters to you. It''s often a sign of depletion, not a shift in how you feel about them.'),
  ('connection', 2, 'Going through the motions in a relationship is a signal worth noticing, not ignoring.', 'Autopilot in a relationship doesn''t necessarily mean it''s over, but it''s usually pointing at something, whether that''s burnout, distance, or an unmet need.'),
  ('connection', 3, 'Not feeling much during a big life event doesn''t mean the event didn''t matter.', 'Emotional response doesn''t always match the size of the moment. A muted reaction can happen even to things that genuinely do matter.'),
  ('connection', 4, 'Feeling like a stranger in your own life is disorienting, but it''s usually temporary.', 'A period of feeling detached from your own routines and choices often reflects overload or unprocessed change, not a permanent shift in who you are.'),
  ('connection', 5, 'Zoning out in conversations that used to interest you might be about capacity, not interest.', 'A drop in engagement with things that used to hold your attention can reflect exhaustion or overload more than an actual loss of interest in the thing.'),
  ('connection', 6, 'Disconnection from your own body is common under prolonged stress.', 'Feeling out of touch with physical sensations, hunger, tiredness, tension, is a frequent response to stress, not a permanent state or a personal failing.'),
  ('connection', 7, 'Not feeling excited about things that used to matter is worth naming, not dismissing.', 'A fading sense of enthusiasm for previously meaningful things is a real signal, even if it doesn''t have one obvious cause behind it.'),
  ('connection', 8, 'Watching your life instead of living it is a real, describable feeling, not an exaggeration.', 'A sense of observing your own life from a slight distance is a recognizable experience, often tied to stress, worth taking seriously rather than brushing off.'),
  ('connection', 9, 'Withdrawing from friends without meaning to still counts as withdrawing.', 'Unintentional distance from people you care about is still distance, and it''s worth noticing before it becomes a longer-term pattern.'),
  ('connection', 10, 'Numbness after a stressful period doesn''t always end when the stress does.', 'The body and mind can stay in a flattened state for a while even after external pressure eases, that lag is common, not a sign something''s permanently wrong.'),
  ('connection', 11, 'Not feeling close to a partner without anything obviously wrong is still worth paying attention to.', 'Emotional distance can build quietly, without a specific incident causing it, which can make it easy to overlook until it''s more pronounced.'),
  ('connection', 12, 'Performing normalcy instead of feeling it takes real effort, even when no one notices.', 'Maintaining an outward sense of okay while feeling disconnected inside is genuinely tiring, even if it looks effortless from the outside.'),
  ('connection', 13, 'Losing touch with old friends often happens gradually, not as a decision.', 'Distance from past friendships is rarely a deliberate choice, it usually accumulates quietly through missed check-ins and shifting priorities.'),
  ('connection', 14, 'Feeling distant during a family gathering doesn''t mean you don''t care about them.', 'Physical presence and emotional presence aren''t always the same thing. Feeling detached in a family setting can happen for reasons unrelated to how much they matter.'),
  ('connection', 15, 'Being physically present with your kids without feeling fully there is common, and worth noticing.', 'Parental exhaustion or distraction can create a sense of going through the motions, even during real time together, that''s a signal worth attending to.'),
  ('connection', 16, 'Feeling disconnected from your own goals doesn''t mean they were never really yours.', 'A fading sense of connection to a goal can reflect burnout or a shift in what you value now, not necessarily that the goal was wrong to begin with.'),
  ('connection', 17, 'Going quiet in group settings you used to enjoy is a real shift worth noticing.', 'A change in how much you engage socially, even in familiar, comfortable settings, is meaningful information, not something to write off automatically.'),
  ('connection', 18, 'Autopilot mode most days is a common response to sustained pressure.', 'Operating on autopilot often develops as a way to get through demanding periods, it''s more a coping pattern than a personal failing.'),
  ('connection', 19, 'Not crying or reacting to something upsetting doesn''t mean you don''t feel it.', 'Emotional response can be delayed, muted, or expressed differently than expected, the absence of visible reaction doesn''t mean the absence of feeling.'),
  ('connection', 20, 'Feeling distant from a version of yourself you recognize is disorienting, but common during change.', 'Significant life shifts can create a gap between who you feel like now and who you remember being, that gap tends to narrow with time and reflection.'),
  ('connection', 21, 'Avoiding calls from people you care about doesn''t mean you''ve stopped caring.', 'Avoidance can develop as a response to depletion or overwhelm, not as a reflection of how much someone still matters to you.'),
  ('connection', 22, 'Intimacy taking more effort than it used to is a real shift, not evidence something''s broken.', 'Closeness naturally requires different amounts of effort at different points in a relationship or in life, that fluctuation is normal, not alarming on its own.'),
  ('connection', 23, 'Not feeling homesick, even far from home, isn''t a sign of not caring about home.', 'The absence of an expected emotional response doesn''t necessarily mean disconnection, it can just mean adaptation happened faster than expected.'),
  ('connection', 24, 'Feeling disconnected from a community you used to be part of is a real, gradual shift.', 'Community ties can loosen slowly, through distance, changed priorities, or simple drift, without any single moment marking the change.'),
  ('connection', 25, 'Feeling disconnected from a past community is a real, gradual shift, not a betrayal.', 'Interests naturally ebb and flow, sometimes a hobby losing its pull is temporary, sometimes it''s a genuine shift, both are normal without needing a reason yet.'),
  ('connection', 26, 'Observing your own emotions from a distance is a real, nameable experience.', 'A sense of watching feelings happen rather than fully experiencing them is a recognizable state, often tied to stress or overload, and worth noticing.'),
  ('connection', 27, 'Not feeling grief the way you expected after a loss doesn''t mean you didn''t love them.', 'Grief doesn''t follow a fixed script, and a delayed, muted, or different-than-expected response is still a valid form of processing loss.'),
  ('connection', 28, 'Feeling distant from your own reflection or sense of self is disorienting but usually temporary.', 'Periods of feeling disconnected from your own identity often accompany major change or stress, and tend to resolve as things settle.'),
  ('connection', 29, 'Withdrawing after being hurt, even from people who didn''t hurt you, is a common protective pattern.', 'Pain from one relationship can create caution that spreads more broadly, even to people who had nothing to do with it, that generalization is common.'),
  ('connection', 30, 'Feeling disconnected during physical closeness is worth noticing, not just pushing past.', 'A gap between physical presence and emotional presence during intimacy is a real signal, often pointing to stress, distraction, or something unspoken.'),
  ('connection', 31, 'Not feeling like celebrating something you worked hard for doesn''t erase the effort behind it.', 'A muted response to your own achievement can happen for many reasons, exhaustion, anticlimax, distraction, none of which diminish what was accomplished.'),
  ('connection', 32, 'Conversations with close people going surface-level is a shift worth naming.', 'A gradual move away from deeper conversation, even with people you''re close to, is a real change in a relationship''s rhythm, not just how things always were.'),
  ('connection', 33, 'Losing the urge to share good news is a meaningful shift, even without a dramatic cause.', 'A fading impulse to tell people about good moments can signal a quieter kind of disconnection, worth noticing even without one clear trigger.'),
  ('connection', 34, 'Feeling distant from your own culture or background can happen gradually, without a single cause.', 'A sense of drift from a cultural or family identity often builds slowly, through distance, life changes, or divided attention, not deliberate rejection.'),
  ('connection', 35, 'Not feeling anything during a conversation that should matter doesn''t mean it doesn''t.', 'A flat emotional response in an important conversation can reflect overload or shock more than actual indifference to what''s being discussed.'),
  ('connection', 36, 'Disconnection from hunger, tiredness, or other body cues is common under chronic stress.', 'Prolonged stress can dull the signals the body usually sends, making it harder to notice basic needs, that''s a physiological pattern, not carelessness.'),
  ('connection', 37, 'Avoiding vulnerability with people who''ve earned trust doesn''t mean the trust isn''t real.', 'Old patterns of guardedness can persist even in relationships that have proven themselves safe, habits built from past experience take time to unlearn.'),
  ('connection', 38, 'A small unresolved conflict can create more distance than its size would suggest.', 'Minor friction left unaddressed can generate a disproportionate sense of distance, since the unresolved part tends to matter more than the original issue.'),
  ('connection', 39, 'Not feeling like yourself around people who know you best is a notable, worth-naming shift.', 'Feeling different or distant even with the people most familiar with you can point to internal change that hasn''t been named yet, not a change in them.'),
  ('connection', 40, 'Feeling disconnected from your own values lately doesn''t mean you''ve lost them.', 'A sense of drift from what usually feels important can be a sign of fatigue or overload rather than an actual change in what you believe.'),
  ('connection', 41, 'Emotional withdrawal after repeated disappointment is a protective pattern, not a character flaw.', 'Pulling back after being let down multiple times is a reasonable response that develops to reduce future hurt, even when it also creates distance.'),
  ('connection', 42, 'Feeling distant during a special occasion doesn''t mean the occasion isn''t meaningful.', 'Emotional presence doesn''t always match the significance of an event, distraction, stress, or overload can create a gap between the two.'),
  ('connection', 43, 'Not feeling connected to work you''re doing well doesn''t mean the work is wrong for you.', 'Competence and emotional connection to a job aren''t the same thing, it''s possible to perform well while feeling detached from the meaning of the work.'),
  ('connection', 44, 'Emotional flatness without a clear cause is common and doesn''t require a dramatic explanation.', 'Stretches of low emotional intensity can happen without an identifiable trigger, and that ambiguity doesn''t make the experience any less real.'),
  ('connection', 45, 'Losing the habit of checking in with people is often about bandwidth, not caring less.', 'A dropped habit of reaching out usually reflects reduced capacity rather than reduced care, even though it can look the same from the outside.'),
  ('connection', 46, 'Not being able to picture your future clearly is disorienting but common during uncertain periods.', 'A blank or hazy sense of what''s ahead often accompanies transition or overwhelm, and tends to sharpen again once some stability returns.'),
  ('connection', 47, 'Not feeling comforted by usually comforting things is worth noticing, not forcing past.', 'When familiar sources of comfort stop working as expected, it can signal something deeper needs attention, rather than needing more of the same comfort.'),
  ('connection', 48, 'Feeling disconnected from a group chat or friend group is a real, common social shift.', 'Drifting from a group you used to feel close to often happens gradually and mutually, without any single falling-out marking the change.'),
  ('connection', 49, 'Withdrawing to avoid getting hurt again is protective, even when it also creates distance.', 'Pulling back after past hurt is a reasonable self-protective instinct, though it''s worth checking whether it''s still serving you in the current relationship.'),
  ('connection', 50, 'Managing people instead of connecting with them is a common pattern under stress or overload.', 'Shifting into a more transactional mode with people close to you can happen when capacity is low, it''s usually circumstantial, not a fixed way of relating.'),
  ('connection', 51, 'Not feeling anticipation for events you used to look forward to is worth naming.', 'A fading sense of excitement for previously anticipated things can be an early signal of burnout or depletion, worth paying attention to.'),
  ('connection', 52, 'Feeling distant from your own body after a health change takes real time to work through.', 'A shift in physical health can create a sense of disconnection from a body that feels less familiar, that adjustment is a real process, not something to rush.'),
  ('connection', 53, 'Losing the sense of being fully known by anyone is a real, describable loneliness.', 'Feeling like no one currently has the full picture of who you are is a specific, nameable kind of disconnection, distinct from simple social isolation.'),
  ('connection', 54, 'Feeling disconnected during a painful conversation can be a protective response, not indifference.', 'Emotional distancing during a difficult topic can be the mind''s way of managing intensity, rather than a sign that the topic doesn''t matter.'),
  ('connection', 55, 'Not feeling the usual pull to reach out first is worth noticing without judgment.', 'A dropped instinct to initiate contact with others often reflects depletion rather than a change in how much the relationship matters.'),
  ('connection', 56, 'Feeling distant from a sense of home, even while living there, is a real and common experience.', 'A place can remain physically the same while the felt sense of home fades, often linked to internal change more than anything about the place itself.'),
  ('connection', 57, 'Withdrawing after feeling let down, without explaining why, is a common but costly pattern.', 'Silent withdrawal can feel safer than naming disappointment, but it also removes the other person''s chance to understand or repair what happened.'),
  ('connection', 58, 'Feeling disconnected from your own sense of humor is a real, notable shift.', 'Losing touch with playfulness or humor can be an early, easy-to-miss sign of depletion, often one of the first things to fade under sustained stress.'),
  ('connection', 59, 'Not feeling like your usual self in your closest relationship is worth naming directly.', 'A shift in how you feel or show up in your most important relationship deserves attention, even without a specific incident explaining it.'),
  ('connection', 60, 'Feeling distant from your own past, like it happened to someone else, is a recognizable experience.', 'A sense of detachment from earlier chapters of your life can happen after significant change, a known experience, not a sign something''s wrong with your memory.'),
  ('comparison', 1, 'A scroll through social media is a highlight reel, not a fair comparison point.', 'Feeling behind after scrolling assumes what you''re seeing is a full, accurate picture of someone else''s life, when it''s really a curated slice of it.'),
  ('comparison', 2, 'A salary comparison rarely accounts for the full picture behind the number.', 'Two salaries can look very different once cost of living, hours worked, and job security are factored in, a single number rarely tells the whole story.'),
  ('comparison', 3, 'Relationship milestones don''t run on a shared timeline.', 'Comparing where you are in a relationship to where peers are assumes a standard schedule exists, when relationships genuinely progress at different paces.'),
  ('comparison', 4, 'A body at the gym next to yours isn''t running the same program, history, or goals.', 'Comparing physiques in the moment ignores years of different training, genetics, and starting points that shaped how each body looks right now.'),
  ('comparison', 5, 'Different parenting choices usually reflect different kids and circumstances, not a better approach.', 'What works for one family doesn''t automatically translate to another, comparing choices directly skips over the context that shaped them.'),
  ('comparison', 6, 'A college friend''s career path isn''t a scoreboard your own is being measured against.', 'Different starting points, industries, and priorities make direct career comparisons between old friends a poor measure of how either of you is doing.'),
  ('comparison', 7, 'A friend''s home reflects their specific finances, timing, and choices, not a universal standard.', 'Comparing homes skips over years of different circumstances, savings, income, luck, and priorities behind each one that don''t transfer to your situation.'),
  ('comparison', 8, 'A put-together life on the outside doesn''t guarantee an easy one underneath.', 'Visible composure says little about what''s actually being managed behind it, most people''s outward presentation is more curated than it looks.'),
  ('comparison', 9, 'A reunion is a two-hour highlight reel, not an accurate cross-section of anyone''s actual life.', 'People tend to share their best updates at reunions, comparing your full, ordinary life to their brief highlights sets up an unfair contrast.'),
  ('comparison', 10, 'A more successful peer''s visible work doesn''t show their years of less visible attempts.', 'Comparing your current output to someone further along skips the earlier, messier stage of their process that you never got to see.'),
  ('comparison', 11, 'A relationship that looks happy from outside isn''t necessarily happier than yours.', 'What''s visible about another relationship is a small, selected slice, comparing your full experience to their highlight reel isn''t a fair measure.'),
  ('comparison', 12, 'A coworker''s visible productivity doesn''t show their actual workload, support, or working style.', 'Comparing output without knowing the full context, task type, team support, personal circumstances, skips too many variables to be a fair measure.'),
  ('comparison', 13, 'Someone else''s finances looking together doesn''t mean they actually are.', 'Financial appearances are often curated or incomplete, comparing your real situation to someone else''s outward presentation rarely reflects reality.'),
  ('comparison', 14, 'A sibling reaching a milestone faster doesn''t set the pace yours has to follow.', 'Family comparisons often ignore how different circumstances, timing, and priorities shaped each person''s path, even within the same family.'),
  ('comparison', 15, 'Bodies recover and change on different timelines for real, individual reasons.', 'Comparing your recovery or fitness progress to someone else''s skips over differences in starting point, genetics, and circumstances that shape the pace.'),
  ('comparison', 16, 'Confidence in meetings is often performed more than it''s felt.', 'Someone appearing confident doesn''t mean they feel certain internally, outward composure and internal experience aren''t always the same thing.'),
  ('comparison', 17, 'Vacation photos capture the best five minutes of a much longer, more ordinary trip.', 'Comparing curated travel photos to your everyday life sets up an unfair contrast between someone''s highlight and your full, unfiltered reality.'),
  ('comparison', 18, 'Follower counts and likes measure reach, not worth or happiness.', 'Online engagement numbers reflect algorithms, timing, and luck as much as anything else, they''re a weak proxy for how good someone''s actual life is.'),
  ('comparison', 19, 'Someone making friends easily doesn''t mean it''s actually effortless for them.', 'Social ease often looks smoother from the outside than it feels on the inside, comparing your effort to their appearance skips the part you can''t see.'),
  ('comparison', 20, 'Someone else having it worse doesn''t cancel out that your own struggle is real.', 'Comparing hardship to dismiss your own difficulty doesn''t actually help either situation, both can be real and worth taking seriously at once.'),
  ('comparison', 21, 'How quickly someone else seems to move on says little about how it actually felt for them.', 'Visible recovery speed after a breakup doesn''t reflect internal process accurately, people process loss at different, often hidden, paces.'),
  ('comparison', 22, 'A wedding or life event doesn''t need to match someone else''s version to have been meaningful.', 'Comparing the scale or style of a personal milestone to someone else''s overlooks that meaning isn''t measured by size or similarity.'),
  ('comparison', 23, 'Someone seeming to have things figured out is usually more performance than reality.', 'Most people are managing more uncertainty than they let on, the appearance of having it together rarely matches the internal experience.'),
  ('comparison', 24, 'Another parent''s patience in a specific moment doesn''t reflect their patience overall.', 'A single snapshot of someone else''s parenting says little about their harder moments, which you likely aren''t seeing.'),
  ('comparison', 25, 'How your decade ''should'' look by now was never a standard anyone actually agreed on.', 'Comparing your life stage to a vague cultural timeline treats an arbitrary benchmark as a real deadline, when it was never actually fixed.'),
  ('comparison', 26, 'Someone enjoying their job outwardly doesn''t mean it''s free of the frustrations yours has.', 'Visible enthusiasm about work is often selective, most jobs include difficulties that don''t make it into someone''s outward description of them.'),
  ('comparison', 27, 'Comparing your inner doubts to someone else''s outward confidence compares two different things.', 'You have full access to your own uncertainty but only see the polished exterior of others, that mismatch makes the comparison inherently unfair.'),
  ('comparison', 28, 'How easily someone else affords things doesn''t reveal what it actually costs them.', 'Visible spending or travel doesn''t show debt, trade-offs, or financial stress behind it, comparing surfaces skips a lot of hidden context.'),
  ('comparison', 29, 'Learning speed varies for real reasons, not just effort or talent.', 'Someone picking up a skill faster might have relevant prior experience, more available time, or simply a different learning style, not more ability.'),
  ('comparison', 30, 'A body after having kids follows a unique, individual path, not a shared timeline.', 'Postpartum recovery and change vary enormously between people for real physiological and circumstantial reasons, comparison rarely accounts for that.'),
  ('comparison', 31, 'Mental health progress isn''t linear or comparable between two different people''s journeys.', 'Someone else''s visible progress doesn''t reflect the same starting point, resources, or challenges as yours, comparing pace overlooks that difference.'),
  ('comparison', 32, 'A peer''s faster promotion doesn''t necessarily reflect a better track record than yours.', 'Promotion timing depends on factors like team openings, manager advocacy, and timing as much as performance, comparison misses most of that context.'),
  ('comparison', 33, 'A more prolific creator''s visible output doesn''t show their private, discarded work.', 'Comparing your finished output to someone else''s visible total skips the much larger, unseen body of work behind their apparent productivity.'),
  ('comparison', 34, 'Having fewer hobbies than someone else isn''t a shortfall, it''s just a different amount of bandwidth.', 'Comparing the breadth of interests assumes more is automatically better, when depth in fewer areas can be just as fulfilling.'),
  ('comparison', 35, 'A busier social calendar doesn''t mean a better one.', 'Comparing the quantity of someone else''s plans to your own overlooks that social satisfaction depends more on quality and fit than on volume.'),
  ('comparison', 36, 'Someone who seems tireless is often just better at hiding fatigue, not immune to it.', 'Visible energy levels are shaped by what people choose to show, comparing your tiredness to their outward stamina skips what''s actually happening underneath.'),
  ('comparison', 37, 'A faster-growing project doesn''t mean yours is failing, growth curves vary widely.', 'Different projects grow at different rates for reasons including timing, market, and resources, comparing trajectories directly skips those differences.'),
  ('comparison', 38, 'How ''adult'' a life looks is a surface measure that misses a lot of what actually matters.', 'Comparing visible markers of adulthood, homeownership, marriage, career, overlooks that a fulfilling life doesn''t require hitting the same checklist.'),
  ('comparison', 39, 'A filtered image isn''t a fair comparison point for an unfiltered reflection.', 'Comparing your actual appearance to edited or curated images sets an unreachable, literally inaccurate standard that isn''t real to begin with.'),
  ('comparison', 40, 'A coworker''s visible work-life balance doesn''t show what they''re sacrificing to maintain it.', 'What looks like effortless balance from outside often involves trade-offs that aren''t visible, comparing the surface skips the full picture.'),
  ('comparison', 41, 'Grief doesn''t move on a schedule that can be measured against someone else''s.', 'Comparing your grieving process to someone else''s pace or expression assumes a normal timeline exists, when grief genuinely varies for each loss.'),
  ('comparison', 42, 'Someone juggling many things well is often showing you the parts that are going smoothly.', 'Visible competence at managing multiple responsibilities rarely includes the dropped balls or private stress behind the scenes.'),
  ('comparison', 43, 'An influencer''s fitness consistency is often part of their job, not a fair baseline.', 'Comparing your routine to someone whose job includes maintaining that routine sets an unrealistic, structurally different standard.'),
  ('comparison', 44, 'An idealized version of a partner isn''t a real person to be measured against.', 'Comparing your real, imperfect patience to a fictional or curated standard of partnership sets a bar that no actual relationship consistently meets.'),
  ('comparison', 45, 'A friend''s savings reflect their specific income and circumstances, not a shared standard.', 'Financial comparisons between friends often ignore differences in income, support, debt, and life stage that shape very different starting points.'),
  ('comparison', 46, 'How quickly you''re ''over'' something isn''t a race with a correct finishing time.', 'Comparing your processing speed to others'' assumes there''s a right pace, when emotional recovery genuinely varies for real, individual reasons.'),
  ('comparison', 47, 'A food photo is composed for the camera, not for accuracy.', 'Comparing your everyday cooking to someone else''s styled photos treats a curated presentation as an honest baseline, when it rarely is.'),
  ('comparison', 48, 'Child development varies significantly and normally between kids.', 'Comparing your child''s milestones to another child''s overlooks the wide, medically normal range that development actually happens within.'),
  ('comparison', 49, 'Someone who seems to bounce back faster may just be showing you less of the struggle.', 'Visible resilience doesn''t always reflect the internal process, some people process difficulty more privately, not necessarily more easily.'),
  ('comparison', 50, 'A friend''s relationship isn''t a scoreboard for your dating life.', 'Comparing your single or dating experience to someone else''s relationship status treats two different situations as if they''re on the same track.'),
  ('comparison', 51, 'A colleague''s recognition doesn''t diminish the value of your own contribution.', 'Visibility and recognition depend on factors beyond just merit, comparing your unacknowledged work to their acknowledged work skips a lot of context.'),
  ('comparison', 52, 'An organized-looking life online is often a curated presentation, not the full reality.', 'What''s shown publicly tends to be the tidiest version of someone''s life, comparing your full, messier reality to their edit isn''t a fair measure.'),
  ('comparison', 53, 'Effortless-looking discipline usually isn''t effortless, it''s just practiced enough to look that way.', 'Comparing your visible struggle with self-discipline to someone else''s polished habits skips the earlier period where it was hard for them too.'),
  ('comparison', 54, 'Confidence in public speaking is a skill built through repetition, not an innate trait.', 'Comparing your nerves to someone else''s ease overlooks how much practice usually sits behind that apparent comfort.'),
  ('comparison', 55, 'A curated highlight reel was never meant to represent full, average life satisfaction.', 'Comparing your day-to-day contentment to someone''s best moments, shared publicly, sets up a mismatch between two very different measures.'),
  ('comparison', 56, 'Healing after loss moves at a pace shaped by the specific loss, not a general schedule.', 'Comparing your grief timeline to someone else''s overlooks how much the nature of the loss and relationship shapes the actual process.'),
  ('comparison', 57, 'Someone bolder creatively isn''t necessarily more talented, just further along in tolerating risk.', 'Creative risk-taking is often a practiced comfort with failure, not an inherent trait, comparing your caution to their boldness skips that development.'),
  ('comparison', 58, 'Calm under pressure is often practiced composure, not the absence of internal stress.', 'Someone who appears unbothered may simply manage their visible reaction differently, not actually experience less internal pressure than you.'),
  ('comparison', 59, 'The life you didn''t choose isn''t guaranteed to have been better, just different.', 'Comparing your actual life to an imagined alternative gives the alternative an unearned advantage, since it never had to face real, lived complications.'),
  ('comparison', 60, 'Someone else''s highlight moment isn''t a fair comparison for your current, ordinary chapter.', 'Comparing your everyday present to someone else''s best, most shared moment stacks an unfair contrast between two very different kinds of time.'),
  ('fear_of_wrong', 1, 'Delaying a decision to avoid choosing wrong still has a cost, the cost of not deciding.', 'Waiting for certainty before deciding treats indecision as risk-free, when in reality, delay itself is a choice with its own consequences.'),
  ('fear_of_wrong', 2, 'A project that''s never started can''t be judged, but it also can''t be finished.', 'Avoiding the start to protect against a bad result also removes any chance of a good one. Fear of imperfection can cost more than an imperfect attempt.'),
  ('fear_of_wrong', 3, 'Endless rewriting before showing anyone often polishes away the point where it was ready.', 'There''s a stage where more revision stops improving the work and starts just delaying the moment of letting it be seen, its own kind of unfinished.'),
  ('fear_of_wrong', 4, 'Being bad at something new is the expected first stage, not a sign you shouldn''t try.', 'Avoiding a new hobby to skip the beginner phase also skips the only path to getting better at it. Early clumsiness is part of the process.'),
  ('fear_of_wrong', 5, 'Not applying removes the chance of a no, and also the chance of a yes.', 'Skipping an application to avoid rejection guarantees the same outcome as being rejected, just without ever finding out what might have happened.'),
  ('fear_of_wrong', 6, 'Overpreparing for a conversation can sometimes replace the conversation itself.', 'Extensive rehearsal to avoid saying the wrong thing can create so much pressure that the real conversation feels harder than it needed to be.'),
  ('fear_of_wrong', 7, 'A new recipe in front of guests carries real risk, and also real, harmless recoverability.', 'Most cooking mistakes are fixable or at worst forgettable, the fear of a flawed dish is usually bigger than the actual consequences of one.'),
  ('fear_of_wrong', 8, 'A wrong call at work is usually a correctable event, not a permanent mark.', 'Most workplace decisions can be adjusted once new information comes in, treating every choice as high-stakes and irreversible often isn''t accurate.'),
  ('fear_of_wrong', 9, 'An unpopular opinion isn''t automatically a wrong one.', 'Avoiding sharing a view because it might not be well-received conflates social risk with actual correctness, they aren''t the same thing.'),
  ('fear_of_wrong', 10, 'Regret after a big purchase is possible either way, buying or not buying.', 'Delaying a decision to avoid future regret ignores that not deciding can also become its own source of regret, just a quieter one.'),
  ('fear_of_wrong', 11, 'Wasted ingredients are a small, recoverable cost for the information a new recipe gives you.', 'The fear of a failed dish is often bigger than the actual downside, a few ingredients, weighed against what''s learned by simply trying.'),
  ('fear_of_wrong', 12, 'Mistakes while speaking a new language are part of how it''s actually learned.', 'Avoiding speaking to prevent errors also prevents the practice that builds fluency, the mistakes are necessary, not a detour from the process.'),
  ('fear_of_wrong', 13, 'A creative risk that flops still produces something a safe choice wouldn''t have.', 'Avoiding bold creative choices to prevent failure also avoids the outcomes only those choices can produce, safety has its own trade-offs.'),
  ('fear_of_wrong', 14, 'A college major rarely locks in a permanent, unchangeable path.', 'Treating an early academic choice as a lifelong decision adds pressure that doesn''t match how flexible most career paths actually turn out to be.'),
  ('fear_of_wrong', 15, 'An email doesn''t need a dozen re-reads to land the right tone.', 'Excessive editing to avoid the wrong tone often adds more anxiety than clarity, most emails read fine well before the final pass.'),
  ('fear_of_wrong', 16, 'Leading a project publicly carries visible risk, but also visible growth.', 'Avoiding leadership roles to sidestep public failure also sidesteps the experience that usually comes with doing it, even imperfectly, in the open.'),
  ('fear_of_wrong', 17, 'Doing a new workout ''wrong'' at first is a normal part of learning form.', 'Avoiding a new routine to prevent doing it incorrectly skips the early, awkward stage almost everyone goes through before movement feels natural.'),
  ('fear_of_wrong', 18, 'There''s no single correct way to raise a child, only ongoing, adjustable choices.', 'Fearing you''ll parent ''the wrong way'' assumes a fixed correct method exists, when most parenting is really a series of imperfect, adaptable decisions.'),
  ('fear_of_wrong', 19, 'Avoiding investing to prevent loss also guarantees missing potential growth.', 'Not investing removes one kind of risk, losing money, while quietly accepting another, the risk of inflation eroding money left untouched.'),
  ('fear_of_wrong', 20, 'Therapy not working perfectly the first time isn''t the same as it not helping at all.', 'Delaying starting therapy for fear it won''t be effective skips the chance to find out, many approaches only reveal their fit after actually trying them.'),
  ('fear_of_wrong', 21, 'There''s rarely such a thing as a truly wrong question.', 'Avoiding a question for fear it''s not the right one usually overestimates how much others are scrutinizing it, most questions are just useful information-gathering.'),
  ('fear_of_wrong', 22, 'The ''perfect'' words for a hard conversation don''t actually exist.', 'Searching for exactly the right phrasing before a difficult talk can delay it indefinitely, since no wording fully removes the discomfort of the topic itself.'),
  ('fear_of_wrong', 23, 'A business that fails still produces real experience the person who never started doesn''t have.', 'Avoiding starting to prevent failure also prevents the specific, hard-won knowledge that usually only comes from actually trying and adjusting.'),
  ('fear_of_wrong', 24, 'Not trying out removes the chance of not making it, and also the chance of making it.', 'Skipping a tryout to avoid the disappointment of not making the cut guarantees the same outcome as not making it, without ever finding out.'),
  ('fear_of_wrong', 25, 'High-stakes decisions benefit from process and checks, not from paralysis.', 'In fields where mistakes carry real weight, the answer is usually careful process and review, not avoidance of decisions altogether, which carries its own risk.'),
  ('fear_of_wrong', 26, 'A text doesn''t need to be analyzed from every angle before it''s sent.', 'Overanalyzing a short message for the ''wrong'' tone often produces more anxiety than the message itself would ever cause once received.'),
  ('fear_of_wrong', 27, 'A public speaking mistake is rarely remembered as clearly by the audience as by the speaker.', 'Avoiding speaking opportunities to prevent visible mistakes usually overestimates how much an audience notices or remembers small stumbles.'),
  ('fear_of_wrong', 28, 'There''s no way to fully verify a partner choice in advance, only reasonable information at the time.', 'Fear of choosing the wrong partner treats relationships as a test with a hidden correct answer, when they''re really an ongoing, adjustable process.'),
  ('fear_of_wrong', 29, 'A ''good enough'' plan acted on tends to beat a ''best'' plan still being searched for.', 'Holding out for the objectively best option before committing can delay action indefinitely, since certainty about which plan is truly optimal rarely arrives.'),
  ('fear_of_wrong', 30, 'Most DIY mistakes are fixable, even the ones that feel intimidating at first.', 'Avoiding home projects to prevent damage often overestimates the actual risk, most beginner mistakes are correctable with some research or help.'),
  ('fear_of_wrong', 31, 'Feedback landing imperfectly doesn''t mean it shouldn''t have been given.', 'Fear of feedback being received badly can prevent useful, needed information from ever being shared, even when the underlying point was worth making.'),
  ('fear_of_wrong', 32, 'Getting lost in a new place is usually a minor, recoverable inconvenience.', 'The fear of losing your way often outweighs the actual, low-stakes cost of it happening, most wrong turns are easily corrected.'),
  ('fear_of_wrong', 33, 'A hard conversation avoided doesn''t stay the same size, it usually grows.', 'Delaying a difficult talk to prevent making things worse often lets the underlying issue continue building, which can make things worse anyway.'),
  ('fear_of_wrong', 34, 'A boundary stated imperfectly is still a boundary.', 'Fear of wording a limit exactly right can prevent it from being set at all, an imperfectly delivered boundary still communicates far more than silence.'),
  ('fear_of_wrong', 35, 'Creative critique is information, not a verdict on your worth as a creator.', 'Avoiding sharing work to prevent criticism also prevents the useful feedback and audience connection that only come from actually putting it out there.'),
  ('fear_of_wrong', 36, 'A decision with no clearly right answer still needs one made.', 'Avoiding choices without an obvious best option can leave you stuck indefinitely, when in reality, several reasonable paths were probably fine.'),
  ('fear_of_wrong', 37, 'There''s rarely one single correct school, just different reasonable fits.', 'Treating a school choice as a make-or-break decision adds pressure that doesn''t reflect how adaptable most kids and families actually are.'),
  ('fear_of_wrong', 38, 'Overpreparing for a presentation to eliminate all risk usually adds pressure instead of removing it.', 'A level of preparation exists that''s genuinely sufficient, beyond that point, extra rehearsal often just increases anxiety without improving performance.'),
  ('fear_of_wrong', 39, 'A meal that doesn''t go perfectly still usually gets the occasion done.', 'Fear of a special-occasion dish flopping often outweighs the actual consequences, most gatherings are remembered for the company, not a flawless menu.'),
  ('fear_of_wrong', 40, 'An early career path rarely locks in permanently.', 'Fear of picking the ''wrong'' first career treats it as a lifelong sentence, when most people''s paths shift and adjust multiple times over a working life.'),
  ('fear_of_wrong', 41, 'Correcting a mistake quickly usually draws less attention than letting it sit.', 'Delaying a fix to avoid drawing attention to an error often makes the eventual correction more noticeable than addressing it right away would have.'),
  ('fear_of_wrong', 42, 'Failing at something physically challenging is part of how capability actually builds.', 'Avoiding a hard physical goal to prevent visible struggle also avoids the process by which most people actually get stronger or more capable.'),
  ('fear_of_wrong', 43, 'Parenting decisions are mostly adjustable, not permanently fixed the moment they''re made.', 'Fearing long-term damage from a single parenting choice overlooks how much course-correction is possible as circumstances and understanding change.'),
  ('fear_of_wrong', 44, 'Negotiating doesn''t require asking for the objectively perfect number, just a reasonable one.', 'Fear of asking for too much in a negotiation can prevent asking for anything meaningful, when most negotiations have room to adjust either way.'),
  ('fear_of_wrong', 45, 'A toast that isn''t flawless still usually does what it''s meant to do.', 'Fear of a speech going wrong tends to focus on polish, when what actually matters to most listeners is sincerity, not technical perfection.'),
  ('fear_of_wrong', 46, 'A first impression rarely locks in a permanent judgment.', 'Fear of a bad first impression assumes people form fixed, unchangeable opinions instantly, when most relationships develop over repeated interactions.'),
  ('fear_of_wrong', 47, 'A past failure describes one attempt, not a guaranteed outcome for the next one.', 'Avoiding a second try because of a past setback assumes the same conditions will repeat, when circumstances, skill, and context usually aren''t identical.'),
  ('fear_of_wrong', 48, 'Past relationship mistakes are information, not a script that has to repeat.', 'Avoiding new relationships to prevent old patterns from recurring skips the chance to apply what was actually learned the first time around.'),
  ('fear_of_wrong', 49, 'Few choices are as truly irreversible as they feel in the moment.', 'Fear of an unfixable wrong decision often overestimates how permanent most choices actually are, many can be adjusted, reversed, or worked around later.'),
  ('fear_of_wrong', 50, 'Asking for what you want imperfectly still communicates more than not asking at all.', 'Fear of phrasing a request the wrong way can prevent it from being made, even an awkward ask usually gets more of the point across than silence.'),
  ('fear_of_wrong', 51, 'Enjoying something you''re not good at is a perfectly valid reason to keep doing it.', 'Avoiding a hobby because of ongoing mediocrity assumes skill is the only reason to do something, when enjoyment on its own is a sufficient one.'),
  ('fear_of_wrong', 52, 'An early read on someone''s character can be updated, it doesn''t have to be right immediately.', 'Fear of misjudging a person often overestimates how fixed a first impression is, most understanding of people develops and adjusts over time.'),
  ('fear_of_wrong', 53, 'A public goal that falls short is still further than a private one that was never set.', 'Avoiding ambition to prevent visible failure also removes the chance of visible progress, which usually happens somewhere in between the two extremes.'),
  ('fear_of_wrong', 54, 'Attempting a fix that doesn''t fully work is usually still better information than not attempting it.', 'Fear of making a problem worse can prevent any action at all, when in most cases, a reasonable attempt either helps or reveals useful next steps.'),
  ('fear_of_wrong', 55, 'A difficult email doesn''t need a perfect tone to land its actual point.', 'Overthinking exact wording in a hard email often delays a message that would have communicated fine with far less editing.'),
  ('fear_of_wrong', 56, 'Art that''s shared imperfectly is still art that exists in the world.', 'Withholding creative work to avoid it being judged also withholds the chance for it to be seen, appreciated, or to simply exist beyond your own hands.'),
  ('fear_of_wrong', 57, 'A decision where every option has a downside still usually has one reasonably better choice.', 'Avoiding a decision because no option is flawless can leave things stuck indefinitely, when picking the least-flawed option is usually still progress.'),
  ('fear_of_wrong', 58, 'Trusted judgment doesn''t require a perfect track record to remain trustworthy.', 'Fear of disappointing people who rely on your judgment assumes any wrong call erases their trust, when most trust survives occasional mistakes just fine.'),
  ('fear_of_wrong', 59, 'A new approach at work that backfires still generates real, useful information.', 'Avoiding a different method to prevent it not working also prevents finding out whether it might have worked, or what to adjust for next time.'),
  ('fear_of_wrong', 60, 'One small mistake is rarely remembered by others as long as it''s remembered by you.', 'Fear that an error will permanently define how you''re seen usually overestimates how much weight other people actually assign to it after the fact.'),
  ('running_empty', 1, 'Waking up tired after a full night''s sleep points to more than just sleep quantity.', 'Persistent morning exhaustion despite adequate hours often signals accumulated depletion, stress, or overload that sleep alone doesn''t fully resolve.'),
  ('running_empty', 2, 'Nothing left to give by day''s end is information, not a personal failing.', 'A depleted feeling at the end of most days is a signal worth listening to, not something to just push through and repeat tomorrow.'),
  ('running_empty', 3, 'Dreading manageable tasks is often a sign of depletion, not a change in the tasks.', 'When previously easy tasks start to feel overwhelming, it usually reflects reduced capacity, not that the tasks themselves have actually gotten harder.'),
  ('running_empty', 4, 'Caffeine can mask fatigue without addressing what''s causing it.', 'Relying on caffeine to push through persistent exhaustion treats the symptom, not the underlying depletion, which tends to keep accumulating underneath.'),
  ('running_empty', 5, 'Increased irritability over small things is often a symptom of exhaustion, not a character shift.', 'A shorter fuse than usual frequently points to depleted reserves rather than an actual change in patience or temperament.'),
  ('running_empty', 6, 'Skipping meals from low energy is a sign worth noticing, not routine.', 'When basic self-care starts slipping due to exhaustion, it''s often one of the clearer signals that capacity has dropped below what''s sustainable.'),
  ('running_empty', 7, 'Feeling behind no matter how much gets done points to workload, not effort.', 'A persistent sense of falling behind despite real output often reflects an unsustainable amount of demand, not a personal shortfall in productivity.'),
  ('running_empty', 8, 'Saying yes without capacity usually borrows from a reserve that''s already low.', 'Agreeing to more when already depleted tends to compound exhaustion rather than distribute it, even when each individual yes seems small.'),
  ('running_empty', 9, 'Feeling depleted after socializing with people you like doesn''t mean you don''t value the time.', 'Social exhaustion, even in enjoyable company, can happen when overall reserves are low, it reflects capacity, not the quality of the relationship.'),
  ('running_empty', 10, 'Pushing through exhaustion symptoms usually delays recovery rather than avoiding the need for it.', 'Ignoring physical or mental signs of depletion to keep going often extends the eventual recovery time rather than preventing the need for rest.'),
  ('running_empty', 11, 'Surviving a week instead of living it is a distinction worth taking seriously.', 'When getting through days replaces actually experiencing them, it''s often a clear sign that current demands have outpaced current capacity.'),
  ('running_empty', 12, 'Losing patience faster with loved ones usually reflects depletion, not diminished care.', 'A shorter temper with the people closest to you often shows up first, precisely because they''re the ones who get the least-guarded version of you.'),
  ('running_empty', 13, 'Guilt about wanting rest doesn''t make the need for rest any less real.', 'Feeling like you have to earn permission to rest adds an extra burden on top of the exhaustion itself, the need is valid regardless of the framing.'),
  ('running_empty', 14, 'Working through lunch out of habit removes one of the few built-in breaks in a day.', 'A skipped break that''s become automatic rather than necessary quietly removes a recovery point that the day was actually built to include.'),
  ('running_empty', 15, 'Feeling numb to normally exciting things is a recognizable sign of depletion.', 'A flattened emotional response, even to good news or fun plans, often reflects how much reserve capacity has been used, not a loss of interest itself.'),
  ('running_empty', 16, 'Struggling to concentrate on simple tasks usually reflects depletion, not declining ability.', 'Difficulty focusing on straightforward things is a common symptom of exhaustion, the skill is still there, the capacity to access it is temporarily reduced.'),
  ('running_empty', 17, 'Weekends no longer feeling like enough recovery time is a signal worth naming.', 'When two days off stop being sufficient to reset, it often means accumulated depletion has outpaced what a normal recovery cycle can restore.'),
  ('running_empty', 18, 'Powering through a busy season without checking in tends to postpone the reckoning, not avoid it.', 'Running on momentum through a demanding stretch without pausing to assess often means the exhaustion catches up later, usually all at once.'),
  ('running_empty', 19, 'Resentment toward once-enjoyed responsibilities often signals depletion, not a real change.', 'When something that used to feel worthwhile starts to feel like a burden, it''s frequently a capacity issue rather than a sign the thing itself changed.'),
  ('running_empty', 20, 'Physical symptoms of stress are the body''s way of asking for attention, not background noise.', 'Headaches, tension, and similar signs are the body''s more direct communication about overload, worth responding to rather than pushing past.'),
  ('running_empty', 21, 'Not having time for a break is usually a sign the break is overdue, not unnecessary.', 'The busier a period feels, the more likely rest is actually needed, even though that''s also when it feels hardest to justify taking any.'),
  ('running_empty', 22, 'Self-care becoming one more task defeats its own purpose.', 'When rest or recovery activities start to feel like added pressure rather than relief, it''s worth reconsidering the approach, not just adding more.'),
  ('running_empty', 23, 'Errands and chores leaving nothing left over is a sign the day''s demands have exceeded its capacity.', 'When all available energy goes to obligations with none left for anything personal, it points to an imbalance worth addressing, not a personal shortcoming.'),
  ('running_empty', 24, 'Losing touch with why something was started often signals depletion more than a loss of purpose.', 'Feeling disconnected from original motivation is a common effect of running low on reserves, not necessarily evidence the goal itself was wrong.'),
  ('running_empty', 25, 'Being constantly ''on'' for others erodes the space needed to simply exist without a role.', 'Ongoing availability for other people''s needs, without offsetting time to just be, tends to steadily deplete reserves that don''t automatically refill.'),
  ('running_empty', 26, 'A patience tank emptying earlier in the day than it used to is a real, trackable shift.', 'Noticing that tolerance runs out sooner than it once did is useful information about current capacity, not a sign of a permanent personality change.'),
  ('running_empty', 27, 'Skipping exercise or hobbies from low energy often deepens the depletion it was meant to relieve.', 'The activities most likely to help with exhaustion are often the first to get cut when energy is low, which can quietly extend the depleted state.'),
  ('running_empty', 28, 'A break creating more to catch up on later doesn''t make the break unnecessary now.', 'Avoiding rest because of the backlog it might create treats short-term relief as not worth a longer-term cost, when rest usually still wins.'),
  ('running_empty', 29, 'Survival mode lasting longer than the situation that triggered it usually needs active attention.', 'A temporary crisis-response state that continues well past the actual crisis often needs a deliberate reset, since it doesn''t tend to switch off on its own.'),
  ('running_empty', 30, 'Feeling flat about real accomplishments often reflects depletion, not a flaw in the achievement.', 'When something objectively worth celebrating doesn''t register as satisfying, exhaustion is often dampening the capacity to feel it, not the achievement itself.'),
  ('running_empty', 31, 'A mind that won''t quiet down at bedtime is often carrying the day''s unprocessed demands.', 'Racing thoughts at night frequently reflect accumulated mental load rather than an isolated sleep problem, addressing the load often helps more.'),
  ('running_empty', 32, 'Feeling solely responsible for holding everything together is a heavy, often self-assigned role.', 'Carrying the sense that everything depends on you is exhausting by design, and it''s worth examining whether that weight is actually yours to hold alone.'),
  ('running_empty', 33, 'Overcommitting at work while personal energy runs out shifts the cost somewhere less visible.', 'Depletion that isn''t showing up at work yet is often showing up elsewhere, in patience, sleep, or mood, the cost doesn''t disappear, it relocates.'),
  ('running_empty', 34, 'Feeling overstimulated by normal contact is a recognizable sign of a depleted nervous system.', 'When ordinary amounts of interaction start to feel like too much, it often reflects overall depletion rather than a change in how much contact you can handle.'),
  ('running_empty', 35, 'Losing interest in things that usually bring joy is a notable symptom, not just a mood.', 'A drop in enjoyment of previously pleasurable activities is a common sign of burnout, worth taking seriously rather than waiting for it to pass.'),
  ('running_empty', 36, 'Not having time to feel the exhaustion doesn''t mean it isn''t accumulating.', 'Pushing through without acknowledging fatigue doesn''t make it go away, it usually just delays when it eventually has to be addressed, often more intensely.'),
  ('running_empty', 37, 'Getting sick right as a busy period ends is a common, recognizable pattern.', 'The body sometimes holds off on breaking down until the pressure demanding it stay functional finally eases, that timing isn''t a coincidence.'),
  ('running_empty', 38, 'Feeling maxed out by ordinary demands signals reduced capacity, not that the demands changed.', 'When everyday tasks start to feel disproportionately taxing, it''s usually a sign baseline energy reserves have dropped, not that daily life got harder.'),
  ('running_empty', 39, 'Struggling with small decisions late in the day is a documented effect of depleted mental energy.', 'Decision fatigue is a real, common experience where the ability to choose, even between small options, wears down over a demanding day.'),
  ('running_empty', 40, 'Pouring from an empty cup is a real limit, not a failure of generosity.', 'Continuing to give to others while personally depleted eventually runs into a hard limit, that''s a resource problem, not a character flaw.'),
  ('running_empty', 41, 'Ignoring your own needs to keep things running for others has a real cost, even when invisible.', 'Consistently deprioritizing your own needs to maintain a household or team tends to accumulate quietly until it eventually demands attention.'),
  ('running_empty', 42, 'Feeling wired but exhausted at once is a recognizable, physiological state, not a contradiction.', 'This combination often reflects a stress response keeping the body activated even while genuine reserves are running low, it''s a real, describable state.'),
  ('running_empty', 43, 'Losing the ability to enjoy downtime without guilt often means rest has felt like it must be earned.', 'Feeling guilty during rest suggests a belief that relaxation needs justification, that belief is worth examining, since rest doesn''t actually require it.'),
  ('running_empty', 44, 'A once-energizing job feeling depleting now is a real, meaningful shift.', 'When work that used to feel invigorating starts to feel draining, it''s often a sign of accumulated burnout rather than the job fundamentally changing.'),
  ('running_empty', 45, 'Struggling to be present with people from depletion reflects capacity, not how much you care.', 'Difficulty being fully present isn''t a measure of how much someone matters to you, it''s often just a sign there''s little reserve left to draw on.'),
  ('running_empty', 46, 'Being stretched across too many responsibilities usually shows up as diminished quality everywhere.', 'Spreading limited capacity across many demands tends to thin out attention and energy across all of them, rather than fully protecting any single one.'),
  ('running_empty', 47, 'Running on willpower alone tends to work until it suddenly doesn''t.', 'Sheer determination can carry someone through demanding stretches for a while, but it''s not a sustainable substitute for actual rest and recovery.'),
  ('running_empty', 48, 'Resenting others'' apparent balance often says more about your own depletion than about them.', 'Envy toward people who seem less exhausted usually reflects how much you''re currently running on empty, not an accurate read of their circumstances.'),
  ('running_empty', 49, 'Cutting sleep to get more done often backfires on the very productivity it was meant to help.', 'Sacrificing rest for output tends to reduce the quality and efficiency of that output, often erasing the time gained by skipping sleep in the first place.'),
  ('running_empty', 50, 'Rest not feeling restorative anymore is a sign worth taking seriously, not ignoring.', 'When usual recovery methods stop working as expected, it often means depletion has reached a point where more than a typical amount of rest is needed.'),
  ('running_empty', 51, 'Repeatedly prioritizing everyone else''s needs before your own eventually runs into a limit.', 'A consistent pattern of self-deprioritization tends to accumulate cost quietly, even when it looks sustainable in any single moment.'),
  ('running_empty', 52, 'Feeling detached from your body''s exhaustion signals is common under chronic overload.', 'Prolonged stress can dull the body''s usual fatigue signals, making it harder to notice depletion until it becomes more severe, a physiological pattern.'),
  ('running_empty', 53, 'Struggling to feel excited about a vacation because of the waiting backlog reflects real stress.', 'Anticipating post-vacation catch-up can genuinely diminish the anticipated relief, that dynamic is worth naming rather than dismissing as ingratitude.'),
  ('running_empty', 54, 'Burnout becoming the normal baseline is worth naming as a shift, not accepting as permanent.', 'When exhaustion stops feeling unusual and starts feeling like the default state, it''s a sign the baseline itself has shifted in a way worth addressing.'),
  ('running_empty', 55, 'Losing motivation for once-enjoyable things often reflects depletion, not lost original interest.', 'A fading pull toward previously enjoyed activities is a common burnout symptom, the interest is often still there underneath the current exhaustion.'),
  ('running_empty', 56, 'Needing more recovery time than others seem to doesn''t require justification.', 'Different people have different capacities and different demands on them, comparing recovery needs to someone else''s visible pace isn''t an accurate measure.'),
  ('running_empty', 57, 'Constantly anticipating the next demand keeps you one step removed from the current moment.', 'Living slightly ahead of the present, always bracing for what''s next, is a common effect of sustained overload, and prevents full presence now.'),
  ('running_empty', 58, 'A tank that never gets a chance to refill between demands eventually runs dry.', 'Continuous output without any recovery interval isn''t sustainable regardless of how manageable each individual demand feels in isolation.'),
  ('running_empty', 59, 'The body signaling a need for a break before the schedule allows one is worth listening to.', 'When physical or mental signs of exhaustion arrive ahead of any planned rest, they''re often the more reliable indicator, worth weighing against the schedule.'),
  ('running_empty', 60, 'Slowing down feeling like it isn''t an option is often the clearest sign that it actually is one.', 'The belief that there''s no room to pause is frequently a symptom of depletion itself, rather than an accurate read of the actual constraints in play.');
