-- New Lens content v2 (2026-08-06): 11 entries x 60 cards from
-- New_Lens_Content.xlsx, replacing the 16-card starter stock.
--
-- Three entries are new (comparison / fear_of_wrong / running_empty) and are
-- NOT dimensions, so lens theming decouples from dimension_t: theme columns
-- widen to text (existing rows/cursors keep their dimension-id keys, so no
-- user progress is lost) and both RPCs are re-created with text params.
-- Reflect crediting still maps each theme to a real dimension in
-- @novame/domain lens-themes.ts.

-- 1) Widen theme columns (index + unique constraint are rebuilt automatically).
alter table public.lens_cards   alter column theme type text using theme::text;
alter table public.lens_progress alter column theme type text using theme::text;

-- 2) Re-create RPCs with text theme params (signature change => drop first).
drop function if exists public.next_lens_card(uuid, dimension_t);
drop function if exists public.submit_lens(uuid, dimension_t, uuid, int, text, date, text, int);

create or replace function public.next_lens_card(
  p_user_id uuid,
  p_theme   text
) returns jsonb
language plpgsql
security definer
set search_path = public
as $$
declare
  v_cursor int;
  v_card   public.lens_cards;
begin
  select last_card_order into v_cursor
  from public.lens_progress
  where user_id = p_user_id and theme = p_theme;
  if not found then
    v_cursor := -1;
  end if;

  select * into v_card
  from public.lens_cards
  where theme = p_theme and is_active and sort_order > v_cursor
  order by sort_order
  limit 1;

  if not found then
    select * into v_card
    from public.lens_cards
    where theme = p_theme and is_active
    order by sort_order
    limit 1;
  end if;

  if not found then
    return jsonb_build_object('found', false);
  end if;

  return jsonb_build_object(
    'found', true,
    'card_id', v_card.id,
    'theme', v_card.theme,
    'sort_order', v_card.sort_order,
    'headline', v_card.headline,
    'body', v_card.body
  );
end;
$$;

revoke all on function public.next_lens_card(uuid, text) from public;
revoke all on function public.next_lens_card(uuid, text) from anon;
revoke all on function public.next_lens_card(uuid, text) from authenticated;
grant execute on function public.next_lens_card(uuid, text) to service_role;

create or replace function public.submit_lens(
  p_user_id    uuid,
  p_theme      text,
  p_card_id    uuid,
  p_card_order int,
  p_response   text,
  p_local_date date,
  p_iso_week   text,
  p_xp_amount  int
) returns jsonb
language plpgsql
security definer
set search_path = public
as $$
declare
  v_completion_id uuid;
  v_new_xp        bigint;
begin
  perform pg_advisory_xact_lock(hashtextextended(p_user_id::text, 0));

  perform 1 from public.companions where user_id = p_user_id;
  if not found then
    return jsonb_build_object('error', 'companion_not_initialized');
  end if;

  values (
    p_user_id, 'new_lens', p_local_date::text,
    jsonb_build_object('theme', p_theme, 'card_id', p_card_id, 'response', p_response),
    p_local_date
  )
  on conflict (user_id, kit, period_key) do nothing
  returning id into v_completion_id;

  if v_completion_id is null then
    return jsonb_build_object('error', 'already_done_this_period');
  end if;

  if p_xp_amount > 0 then
    values (p_user_id, 'new_lens', p_xp_amount, v_completion_id, p_local_date, p_iso_week);
  end if;

  values (p_user_id, p_theme, p_card_order, now())
  on conflict (user_id, theme)
    do update set last_card_order = excluded.last_card_order, updated_at = now();

  select coalesce(sum(amount), 0) into v_new_xp
  from public.xp_events where user_id = p_user_id;
  update public.companions set xp = v_new_xp, last_opened_at = now()
  where user_id = p_user_id;

  return jsonb_build_object(
    'error', null,
    'completion_id', v_completion_id,
    'xp_awarded', coalesce(p_xp_amount, 0),
    'companion_xp', v_new_xp,
    'response', p_response
  );
end;
$$;

revoke all on function public.submit_lens(uuid, text, uuid, int, text, date, text, int) from public;
revoke all on function public.submit_lens(uuid, text, uuid, int, text, date, text, int) from anon;
revoke all on function public.submit_lens(uuid, text, uuid, int, text, date, text, int) from authenticated;
grant execute on function public.submit_lens(uuid, text, uuid, int, text, date, text, int) to service_role;

-- 3) Replace the card library.
delete from public.lens_cards;
